INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7125', 'spa', 'Salir al encuentro; como infinitivo constructo liqra''t funciona como preposición: ''hacia, contra, enfrente de.''', 'En la gran mayoría de sus apariciones, esta raíz se presenta como el infinitivo constructo liqra''t, que ha llegado a funcionar como una verdadera preposición con el sentido de ''al encuentro de, hacia, contra.'' Abarca todo el espectro de encuentros: la bienvenida gozosa (Éx 18:7, Jetro saliendo al encuentro de Moisés), la confrontación militar (1 Sam 17:48, David corriendo al encuentro de Goliat) y la recepción diplomática (Gn 14:17). El vocablo capta el movimiento intencional y dirigido hacia otra persona o grupo. Una aparición enigmática en Génesis 15:10, donde Abram dispone las mitades de los animales ''cada parte frente a su correspondiente,'' conserva el sentido raíz de correspondencia espacial más que de encuentro personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7126', 'spa', 'Acercarse, aproximarse; en Hifil, presentar una ofrenda; estativo: estar cerca, estar a la mano.', 'Uno de los verbos con mayor densidad teológica de la Biblia hebrea, esta raíz abarca todo el espectro de la cercanía: desde una persona que se aproxima a otra, hasta el acto solemne de presentar un sacrificio ante Dios. En su conjugación Hifil, que representa casi la mitad de todas las apariciones, se convierte en el término técnico estándar para ofrecer sacrificios en el sistema levítico. Sin embargo, el vocablo nunca pierde su núcleo espacial y concreto: a Moisés se le dice que ''se acerque'' a la zarza ardiente, los ejércitos ''se aproximan'' para la batalla y el día de Yahvé ''está cerca.'' El Piel intensifica la acción como un acercamiento deliberado y solemne.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7127', 'spa', 'Acercarse, aproximarse; ofrecer sacrificio; presentar a alguien ante otro (verbo arameo en Daniel/Esdras)', 'Verbo arameo que aparece exclusivamente en Daniel y Esdras, con la idea central de acercarse. En su forma Qal más simple describe aproximación física: Daniel acercándose a un intérprete (Dn 7:16) o acusadores presentándose ante el rey (Dn 3:8). Las formas Piel y Hifil extienden el significado al ámbito cultual: llevar ofrendas al altar (Esd 6:17; 7:17). De modo especialmente notable, en Daniel 7:13 el Hijo del Hombre es «llevado» ante el Anciano de Días —una presentación que trasciende la mera proximidad física y conlleva matices de investidura real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7128', 'spa', 'Batalla, guerra, conflicto armado; préstamo arameo usado en textos poéticos y bíblicos tardíos.', 'Préstamo del arameo (cf. siríaco qrav) que significa «batalla» o «guerra», presente en la literatura poética y sapiencial más que en la narrativa histórica. Funciona como sinónimo de מִלְחָמָה pero con un registro más literario. El Salmo 55:22 declara memorablemente «su corazón era guerra» (קְרָב), y Eclesiastés 9:18 advierte que «un solo pecador destruye mucho bien» con la expresión «armas de guerra» (כְּלֵי קְרָב). El español «batalla» y el francés «bataille» captan directamente el sentido militar, mientras que el alemán traduce algunas ocurrencias como «Mitte» (centro), reflejando la forma prepositiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7130', 'spa', 'Interior, medio, entrañas; la parte interna de un cuerpo, el centro social de un grupo o las vísceras de un animal sacrificial.', 'Este sustantivo ocupa el espacio entre la geografía y la anatomía en el pensamiento hebreo. Con mayor frecuencia aparece con preposición — beqereb (''en medio de'') o miqqereb (''de en medio de'') — para situar algo en el corazón de una comunidad, ciudad o territorio: Dios habitando ''en medio de'' Israel, o un malhechor cortado ''de en medio de'' la congregación. Pero el mismo vocablo puede volcarse hacia adentro para describir la sede de las emociones y el pensamiento dentro de una persona, donde Sara ríe ''dentro de sí'' (Gn 18:12) y donde el espíritu se conmueve. En su sentido más concreto, nombra las entrañas de un animal sacrificial, los órganos cubiertos de grasa que se colocan sobre el altar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7131', 'spa', 'Que se acerca, que se aproxima; adjetivo verbal de qarab, usado predicativa y sustantivamente para quien se acerca.', 'Adjetivo verbal derivado de la raíz qarab (''acercarse''). Qareb describe a alguien o algo en el acto de aproximarse. Funciona predicativamente, como cuando el filisteo Goliat avanza de forma constante hacia David (1 S 17:41), y también sustantivamente para designar a quienes se acercan al tabernáculo o templo para el servicio sagrado (Nm 1:51; Ez 40:46; 45:4). En Deuteronomio 20:3, se dirige a los soldados que se aproximan para la batalla. Las glosas multilingües — español ''acercarse'', francés ''approchant'' — captan la cualidad progresiva y direccional de movimiento hacia un objetivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7133a', 'spa', 'Ofrenda, oblación (qorbán): el término levítico estándar para cualquier don presentado ante Dios en el santuario.', 'Ofrenda, oblación (qorbán): el término levítico estándar para cualquier don presentado ante Dios en el santuario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7134', 'spa', 'Hacha (herramienta de corte para talar arboles y trabajar la madera)', 'Sustantivo que designa el hacha, un implemento pesado para cortar madera. Abimélec toma su hacha para cortar ramas en el monte Zalmon durante su asalto a la torre de Siquem (Jue 9:48). En 1 Samuel 13:20-21 aparece entre las herramientas agricolas que los israelitas debian llevar a afilar con los filisteos, revelando su sometimiento. El Salmo 74:5 retrata al enemigo destrozando con hachas la talla de madera del templo, y Jeremias 46:22 compara al ejercito invasor con lenadores que avanzan con hachas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7135', 'spa', 'frío, frialdad (condición climática invernal, nocturna o atmosférica)', 'Sustantivo femenino que designa el frío o la frialdad como fenómeno meteorológico. Nahúm 3:17 compara a los guardias de Nínive con langostas posadas en los muros en un día frío que huyen al salir el sol. Proverbios 25:20 advierte que cantar canciones a un corazón afligido es como quitar la ropa en día de frío. Job 24:7 describe a los desamparados sin abrigo contra el frío nocturno, mientras que Job 37:9 atribuye el frío a los vientos dispersantes. Salmo 147:17 pregunta quién puede resistir el frío de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7136a', 'spa', 'Encontrar, hallar o suceder; de eventos que le acontecen a alguien, de personas que se encuentran entre sí, o de hacer que algo suceda.', 'Encontrar, hallar o suceder; de eventos que le acontecen a alguien, de personas que se encuentran entre sí, o de hacer que algo suceda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7136b', 'spa', 'enmaderar, poner vigas (construcción de techos, puertas y aposentos altos)', 'Verbo denominativo en Piel que significa colocar o asentar vigas: un término técnico de construcción. En el relato de la reconstrucción de Nehemías aparece tres veces: Nehemías solicita madera para enmaderar las puertas de la ciudadela (2:8), y dos grupos de obreros ''colocaron sus vigas'' al reparar los muros de Jerusalén (3:3, 3:6). Segunda Crónicas 34:11 lo emplea para la restauración del templo bajo Josías. De modo notable, Salmo 104:3 lo aplica a Dios, quien ''pone las vigas'' de sus aposentos altos sobre las aguas, una imagen cosmológica majestuosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7138', 'spa', 'Cercano, próximo; espacialmente inmediato, temporalmente inminente, relacionalmente pariente, o cultualmente admitido a la presencia de Dios.', 'Cercano, próximo; espacialmente inmediato, temporalmente inminente, relacionalmente pariente, o cultualmente admitido a la presencia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7139', 'spa', 'Rasurar la cabeza, hacerse calvo — rito de duelo que implica la remoción deliberada del cabello como expresión de luto.', 'Se refiere a la práctica del antiguo Cercano Oriente de rasurar o arrancarse el cabello de la cabeza como señal visible de duelo y lamentación. Levítico 21:5 prohíbe expresamente a los sacerdotes realizar este rito, situándolo junto a otras formas de automutilación vedadas para los consagrados a Dios. Miqueas ordena a Sión ''hazte calva y trasquílate'' por los hijos que van al exilio (Miq 1:16), convirtiendo la costumbre de duelo en un llamado profético. El verbo aparece en múltiples formas verbales (Qal, Nifal, Hifil, Hofal), todas preservando el significado central de calvicie inducida ritualmente como duelo hecho visible en el cuerpo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7140', 'spa', 'Hielo, escarcha; agua congelada como fenómeno natural del clima frío.', 'Sustantivo que designa hielo o escarcha: agua congelada en sus formas naturales. Jacob invoca la escarcha nocturna que lo consumía durante sus años con Labán (Gn 31:40). Job y los Salmos celebran el hielo como manifestación del poder soberano de Dios sobre la creación: el agua se endurece como piedra (Job 37:10), el hielo tiene un origen misterioso (Job 38:29), y Dios lanza su hielo como pedazos (Sal 147:17). Ezequiel 1:22 emplea la palabra para describir la imponente extensión sobre los seres vivientes, ''resplandeciente como hielo''. El español ''hielo'' y el inglés ''ice/frost'' confirman el rango semántico unificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7141', 'spa', 'Coré — nombre propio que posiblemente significa ''calvicie,'' llevado por levitas rebeldes, jefes edomitas y clanes de cantores de salmos', 'Coré — nombre propio que posiblemente significa ''calvicie,'' llevado por levitas rebeldes, jefes edomitas y clanes de cantores de salmos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7142', 'spa', 'calvo, de cabeza calva (naturalmente o por enfermedad)', 'Este adjetivo describe calvicie de la cabeza, apareciendo tanto en contextos de pureza legal como en burla narrativa. Levítico 13:40 distingue la calvicie natural en la parte posterior de la cabeza de condiciones de enfermedad, declarando limpio al hombre naturalmente calvo. El infame incidente en 2 Reyes 2:23 tiene jóvenes burlándose de Eliseo con el epíteto repetido ''¡calvo!''—si se refiere a calvicie natural, afeitado ritual, o se pretende metafóricamente permanece debatido. El término en sí es neutral, aunque el contexto determina si es descriptivo o despectivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7143', 'spa', 'Nombre propio que significa ''calvo'', llevado por el padre de Johanán y Jonatán, líderes militares que se reunieron con Gedalías después de que Nabucod', 'Nombre propio que significa ''calvo'', llevado por el padre de Johanán y Jonatán, líderes militares que se reunieron con Gedalías después de que Nabucodonosor lo nombró gobernador del remanente en Judá. El hijo de Carea, Johanán, advirtió a Gedalías de la conspiración de asesinato tramada por Ismael hijo de Netanías (Jer 40:13-16), y tras el asesinato, condujo a la comunidad sobreviviente — en contra del consejo de Jeremías — a Egipto (Jer 41-43). El nombre aparece en el relato paralelo de 2 Reyes 25:23 y se repite a lo largo de Jeremías 40-43. La tradición griega lo transcribe como Καρηε/Καρηθ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7144', 'spa', 'Calvicie, especialmente una zona rapada en la cabeza como señal de duelo, prohibida para sacerdotes e Israel', 'Se refiere a una zona pelada en la cabeza producida al raparse como rito de duelo. Los pueblos del antiguo Cercano Oriente comúnmente se rapaban la cabeza para expresar aflicción, pero la ley israelita restringió esta práctica: los sacerdotes no deben hacerse calva en sus cabezas (Lv 21:5), y al pueblo se le ordena no cortarse ni hacerse calva por los muertos (Dt 14:1). Cuando Isaías profetiza juicio, la calvicie reemplaza al cabello bien peinado (Is 3:24), y la devastación de Moab trae calvicie sobre toda cabeza (Is 15:2). El término captura la naturaleza visible e intencional de esta señal de duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7145', 'spa', 'Coraíta; adjetivo gentilicio que designa a los miembros del clan levítico descendiente de Coré hijo de Izhar.', 'Este adjetivo gentilicio identifica a los miembros de la familia levítica descendiente de Coré hijo de Izhar, y siempre aparece con el artículo definido. Los coraítas servían como porteros y músicos del templo, según se detalla en Crónicas (1 Cr 9:19, 31; 12:7; 26:1, 19). Figuran entre los clanes levíticos en Números 26:58 y Éxodo 6:24. Segunda Crónicas 20:19 registra cómo se levantaron para alabar al Señor antes de la batalla de Josafat. Los títulos de salmos atribuidos a ''los hijos de Coré'' probablemente designan a este mismo gremio. El español ''coraíta'' preserva la conexión patronímica con su ancestro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7146', 'spa', 'calvicie en la parte posterior de la cabeza', 'Este termino tecnico en la legislacion levitica de pureza distingue la calvicie en la coronilla o parte posterior de la cabeza de la calvicie frontal. Siempre contrastado con la calvicie de la frente, aparece exclusivamente en las regulaciones sobre enfermedades cutaneas de Levitico 13, donde la ubicacion de los sintomas importa para el diagnostico. El termino refleja la cuidadosa atencion del antiguo Israel a los sintomas corporales en la pureza cultual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7147', 'spa', 'Hostilidad, oposición; actitud desafiante contra Dios expresada como caminar ''en contra'' de él', 'Sustantivo que significa ''oposición'' u ''hostilidad'', usado exclusivamente en Levítico 26 en la expresión idiomática ''caminar en hostilidad con'' alguien. Describe la postura obstinada y desafiante de Israel hacia Dios, y la correspondiente respuesta divina en igual medida. Las maldiciones escalonadas del capítulo giran en torno a esta palabra: si Israel camina en oposición a Dios (vv. 21, 23, 27, 40), Dios caminará en oposición a ellos (vv. 24, 28, 41). La repetición séptuple en un solo capítulo subraya su peso retórico como la palabra definitoria de la rebeldía contra el pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7148', 'spa', 'convocados, representantes designados o líderes nombrados oficialmente', 'Este participio pasivo funciona como término técnico para representantes oficialmente convocados o nombrados en la asamblea de Israel. Números lo usa para designar a los líderes tribales escogidos para representar a sus clanes en la congregación—literalmente ''los convocados de la asamblea'' o ''los citados de la reunión señalada.'' No eran voluntarios sino consejeros oficialmente designados, portadores de autoridad representativa para sus tribus.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7149', 'spa', 'Ciudad, urbe (arameo); usado en Esdras 4 para referirse a Jerusalén en correspondencia oficial persa.', 'Sustantivo femenino arameo que significa «ciudad», cognado del hebreo קִרְיָה, presente exclusivamente en la sección aramea de Esdras (4:10-21). Designa a Jerusalén en el contexto de correspondencia oficial persa, donde los funcionarios provinciales advierten al rey Artajerjes que los judíos están reconstruyendo «esta ciudad rebelde y malvada». El término porta connotaciones administrativas y políticas, ya que las cartas describen el historial sedicioso de la ciudad. El español «ciudad», el francés «ville» y el alemán «Stadt» lo traducen con la palabra estándar para un centro urbano establecido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7151', 'spa', 'Ciudad, villa — sinónimo poético y elevado de עִיר, usado especialmente para Jerusalén en textos proféticos y litúrgicos.', 'Ciudad, villa — sinónimo poético y elevado de עִיר, usado especialmente para Jerusalén en textos proféticos y litúrgicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7152', 'spa', 'Queriot (topónimo, lit. ''ciudades''); dos localidades bíblicas en Judá y Moab', 'Este topónimo, formado como plural intensivo de ''ciudad'', identifica dos lugares distintos: uno en Judá, posiblemente la actual Qaryatein al sur de Hebrón, y otro en Moab, probablemente la antigua Rabat-Moab (hoy Rabba). El sitio moabita aparece en oráculos proféticos contra Moab y en la célebre estela de Mesá. La forma plural del nombre puede indicar una ciudad de gran importancia o un conjunto de asentamientos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7153', 'spa', 'Quiriat-Arba, antiguo nombre cananeo de Hebrón, que significa ''ciudad de cuatro'' o ''ciudad de Arba.''', 'El antiguo nombre cananeo de la ciudad que después se conoció como Hebrón, compuesto de qiryat (''ciudad de'') y arba'' (''cuatro'') o el nombre propio Arba. Aparece en las narraciones patriarcales: la muerte y sepultura de Sara en la cueva de Macpela (Gn 23:2) y el regreso de Jacob junto a su padre Isaac (Gn 35:27). También figura en los relatos de conquista y reparto de Josué (Jos 14:15; 15:13, 54; 20:7; 21:11). La transliteración uniforme ''Quiriat-Arba'' en las distintas lenguas confirma su tratamiento como topónimo transliterado, no traducido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7156', 'spa', 'Quiriataim, topónimo de ciudades en Transjordania: una en Moab (actual Qureyat) y otra ciudad levítica en Neftalí', 'Quiriataim (''ciudad doble'', de la forma dual de qiryah) designa al menos dos localidades distintas en la Biblia hebrea. La principal es una ciudad en Moab, vinculada al territorio de Rubén (Núm 32:37; Jos 13:19), escenario de una batalla en la época de Abraham (Gén 14:5) y objeto de oráculos proféticos contra Moab (Jer 48:1, 23; Ezeq 25:9), probablemente la actual Qureyat al sureste del monte Ataro. Una segunda Quiriataim fue ciudad levítica en Neftalí (1 Cr 6:76), correspondiente a Cartán en Josué 21:32. La terminación dual sugiere un asentamiento gemelo o pueblos emparejados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7157', 'spa', 'Quiriat-Jearim — ciudad gabaonita en la frontera de Judá y Benjamín donde reposó el arca tras su regreso de Filistea.', 'Quiriat-Jearim — ciudad gabaonita en la frontera de Judá y Benjamín donde reposó el arca tras su regreso de Filistea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7158', 'spa', 'Quiriat-Sefer (nombre antiguo de Debir, significa ''ciudad del libro/escriba'')', 'Topónimo cananeo antiguo que significa ''ciudad del libro'' o ''ciudad del escriba'', identificado como el nombre anterior de Debir en la serranía meridional de Judá. El nombre aparece en el relato de la conquista de Caleb, quien ofrece a su hija Acsa a quien capture Quiriat-Sefer, desafío aceptado por Otoniel (Josué 15:15-16; Jueces 1:11-12). Josué 15:49 conserva la variante Quiriat-Saná. El sitio se identifica probablemente con la actual Dhahiriyye, al suroeste de Hebrón. Todas las lenguas meta transliteran el nombre de forma consistente, confirmando su condición de nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7160', 'spa', 'Resplandecer, irradiar rayos; tener cuernos desarrollados', 'Este verbo opera en dos campos semánticos mediante uso denominativo: desde ''cuerno'' significa ''mostrar cuernos'' (plenamente desarrollados); desde ''rayo'' significa ''irradiar, resplandecer''. Su uso más célebre describe el rostro de Moisés resplandeciendo tras encontrarse con la gloria de Dios en el Sinaí, pasaje que influyó en representaciones artísticas, incluido el Moisés cornudo de Miguel Ángel, basado en el latín cornuta. La coincidencia semántica entre cuernos y rayos refleja la iconografía antigua donde la radiancia divina se representaba como proyecciones en forma de cuerno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7161a', 'spa', 'Cuerno de animal o del altar; metafóricamente, fuerza, poder o dignidad; también colina o ladera, y rayos de luz de una teofanía.', 'Cuerno de animal o del altar; metafóricamente, fuerza, poder o dignidad; también colina o ladera, y rayos de luz de una teofanía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7162', 'spa', 'Este sustantivo arameo aparece exclusivamente en Daniel, con dos significados claramente distintos. En la orquesta de Nabucodonosor (Dan 3:5, 7, 10, 1', 'Este sustantivo arameo aparece exclusivamente en Daniel, con dos significados claramente distintos. En la orquesta de Nabucodonosor (Dan 3:5, 7, 10, 15), designa un cuerno musical que se toca junto a otros instrumentos como señal para adorar. En las visiones nocturnas de Daniel (Dan 7:7-24), los cuernos brotan de bestias y representan reyes y reinos — símbolos de poder político. El contexto de cada pasaje determina de manera decisiva si se trata del instrumento o del símbolo apocalíptico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7165', 'spa', 'Broche o corchete; sujetador metálico (de oro o bronce) usado para unir las cortinas del tabernáculo.', 'Término técnico para los broches o corchetes metálicos que unían las cortinas del tabernáculo, con aparición exclusiva en Éxodo. Los broches de oro sujetaban las diez cortinas interiores de lino formando una sola cubierta (Éx 26:6; 36:13), mientras que los broches de bronce unían las once cortinas de pelo de cabra de la tienda exterior (Éx 26:11; 36:18). Estas pequeñas pero esenciales piezas transformaban paneles separados en una estructura única y cohesionada, garantizando la integridad del santuario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7167', 'spa', 'Rasgar o desgarrar, especialmente vestiduras en señal de duelo o ira; también ser rasgado (Nifal) o cortar, partir en dos.', 'Rasgar o desgarrar, especialmente vestiduras en señal de duelo o ira; también ser rasgado (Nifal) o cortar, partir en dos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7168', 'spa', 'Pedazos de vestidura rasgados, harapos, jirones', 'Este sustantivo designa trozos de tela rasgados, ya sean vestiduras desgarradas deliberadamente (como en el acto simbólico de rasgar el manto de Jeroboam en doce pedazos) o harapos gastados que denotan pobreza. La raíz transmite la idea de un desgarro violento, y la forma plural subraya la multiplicidad de fragmentos. Las vestiduras rasgadas tenían un poderoso peso simbólico en el antiguo Israel, marcando duelo, juicio o actos proféticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7169', 'spa', 'pellizcar, arrancar; guiñar el ojo o apretar los labios con malicia; ser formado del barro', 'El verbo hebreo קָרַץ transmite un movimiento vívido de pellizcar o arrancar. En Proverbios describe un lenguaje corporal engañoso: guiñar el ojo (Prov 6:13; 10:10) y apretar los labios (Prov 16:30) como gestos de maquinación maliciosa. Salmo 35:19 lo emplea de manera similar para enemigos que guiñan con intención hostil. En Job 33:6, la forma pasiva retrata el ser ''arrancado'' del barro, evocando al alfarero que moldea la figura humana, en paralelo con la imaginería acadia del dios formando a Enkidu del barro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7172', 'spa', 'Piso, suelo, fondo; la superficie plana de base de un edificio (templo, tabernáculo) o el fondo del mar', 'Sustantivo probablemente derivado por reduplicación de la raíz qrr o qur, קַרְקַע designa el piso o superficie a nivel del suelo de una estructura. Aparece con mayor prominencia en la descripción del templo de Salomón, cuyo piso se recubrió de oro (1 Re 6:15, 16, 30), y en el ritual del tabernáculo de Números 5:17, donde se toma polvo del piso. Amós 9:3 extiende la imagen de forma dramática al ''fondo del mar'', el lecho oceánico donde los fugitivos podrían intentar esconderse de Dios. El término captura la idea de una superficie horizontal de base.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7175', 'spa', 'Tablón o bastidor estructural, especialmente los marcos de madera de acacia del Tabernáculo; una vez el entablado de la cubierta de un barco.', 'Tablón o bastidor estructural, especialmente los marcos de madera de acacia del Tabernáculo; una vez el entablado de la cubierta de un barco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7176', 'spa', 'ciudad, urbe (forma poética/tardía)', 'Sinónimo poético tardío de los vocablos hebreos más comunes para ciudad. Aparece exclusivamente en la literatura sapiencial: Job lo usa para la puerta de su propia ciudad donde se sentaba como anciano (Job 29:7), mientras que Proverbios lo emplea como escenario urbano de la Sabiduría personificada, que clama desde las alturas y las puertas de la ciudad (Prov 8:3; 9:3, 14). En Proverbios 11:11 la ciudad representa una comunidad corporativa bendecida o arruinada por sus habitantes. El cognado fenicio qart aparece en topónimos como Cartago (Qart-Hadasht, ''ciudad nueva'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7179', 'spa', 'Rastrojo, paja, hojarasca seca — material vegetal seco usado como imagen de lo que es inútil, inflamable o arrastrado por el viento. Sustantivo mascul', 'Rastrojo, paja, hojarasca seca — material vegetal seco usado como imagen de lo que es inútil, inflamable o arrastrado por el viento. Sustantivo masculino para los tallos secos y la paja que quedan tras la cosecha, que aparece casi exclusivamente en símiles y metáforas. Su sentido literal surge solo una vez, cuando los israelitas deben recoger rastrojo para hacer ladrillos (Éx 5:12). En todos los demás casos, קַשׁ sirve a propósitos figurativos: el fuego consume a los enemigos como rastrojo (Éx 15:7; Is 5:24; 47:14; Nah 1:10; Jl 2:5; Abd 18; Mal 3:19), el viento dispersa a los malvados como paja (Is 40:24; 41:2; Jer 13:24; Sal 83:14), y Job se compara a sí mismo con rastrojo sin valor ante Dios (Job 13:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7181', 'spa', 'Prestar atención, escuchar con cuidado, dar oído; escucha atenta que implica obediencia', 'Prestar atención, escuchar con cuidado, dar oído; escucha atenta que implica obediencia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7182', 'spa', 'Atención, escucha atenta, respuesta o señal de vida', 'Este sustantivo denota la atención o el acto de prestar oído, frecuentemente como señal de vida o capacidad de respuesta. Aparece en contextos que ponen a prueba la respuesta divina o la vitalidad humana. Funciona como sustantivo verbal abstracto derivado de la raíz que significa ''atender, prestar atención'', y puede usarse como acusativo cognado para intensificar la idea verbal de dar atención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7183b', 'spa', 'atento, escuchando cuidadosamente (de oídos)', 'Este adjetivo, que aparece solamente en forma plural femenina, describe oídos que están atentos y alertas para escuchar. Ocurre exclusivamente en la frase ''estén tus oídos atentos,'' usada en oraciones pidiendo a Dios que escuche cuidadosamente la súplica. El término aparece en la oración de dedicación del templo de Salomón en 2 Crónicas y en el clamor desde lo profundo del Salmo 130, enfatizando la petición de atención divina en vez de una audición pasiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7184', 'spa', 'Jarras o copas rituales para libaciones en el tabernáculo y el templo', 'Este término designa un tipo específico de vasija empleada en el servicio del tabernáculo y del templo, asociada con las ofrendas de libación. Su forma y material exactos son inciertos, pero el contexto cúltico constante sugiere importancia ritual. Estas jarras aparecen en las listas de utensilios para la mesa de los panes de la proposición y en los inventarios sacerdotales de objetos sagrados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7185', 'spa', 'Ser duro, severo o difícil; en Hifil, endurecer u obstinar; del parto difícil, trato severo y carácter feroz.', 'Ser duro, severo o difícil; en Hifil, endurecer u obstinar; del parto difícil, trato severo y carácter feroz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7186', 'spa', 'Duro, severo, áspero — que describe circunstancias difíciles, carácter obstinado, trato cruel o intensidad feroz', 'Duro, severo, áspero — que describe circunstancias difíciles, carácter obstinado, trato cruel o intensidad feroz');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7192', 'spa', 'quesitá, unidad antigua de valor o peso (posiblemente plata)', 'La quesitá era una unidad de valor usada en el período patriarcal, aunque su peso o valor preciso permanece desconocido para nosotros. Jacob compró terreno en Siquem por cien quesitás, y los consoladores de Job cada uno le dio una quesitá junto con un anillo de oro como regalo de restauración. El término no aparece en ningún otro lugar de las Escrituras y aparentemente se había vuelto arcaico u obsoleto para tiempos bíblicos posteriores, sugiriendo que pertenece a la práctica económica israelita muy temprana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7193', 'spa', 'Escama (de pez o reptil); usada en leyes dietéticas para criaturas acuáticas y metafóricamente de coraza escamada', 'Este sustantivo designa la escama de un pez o reptil, con presencia destacada en las leyes dietéticas levíticas donde las criaturas acuáticas deben tener tanto aletas (סְנַפִּיר) como escamas (קַשְׂקֶשֶׂת) para ser consideradas limpias (Lev 11:9-12; Deut 14:9-10). La misma palabra aparece en 1 Samuel 17:5 para la ''cota de escamas'' de Goliat, cuyas placas de metal superpuestas semejaban escamas de pez. En Ezequiel 29:4, el Faraón es representado como un gran cocodrilo cuyas escamas se adhieren a los peces del Nilo, imagen vívida de dominación imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7194', 'spa', 'Atar, amarrar; conspirar, tramar un complot; participio: conspirador; pasivo: atado, ligado; del ganado: fuerte, robusto', 'Atar, amarrar; conspirar, tramar un complot; participio: conspirador; pasivo: atado, ligado; del ganado: fuerte, robusto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7195', 'spa', 'Conspiración — complot secreto y traicionero contra un gobernante o autoridad establecida. El único significado de este sustantivo masculino es un com', 'Conspiración — complot secreto y traicionero contra un gobernante o autoridad establecida. El único significado de este sustantivo masculino es un complot clandestino para derrocar a un rey o gobierno. Aparece como término técnico en las narrativas políticas de Reyes y Crónicas, frecuentemente en la expresión formulaica ''conspiró una conspiración'' (קָשַׁר קֶשֶׁר), como con Zimri contra Elá (1 Re 16:20), Jehú contra Joram (2 Re 15:15) y Oseas contra Pecaj (2 Re 15:30). La reina Atalía grita ''¡Conspiración! ¡Conspiración!'' al descubrir que el golpe ha fracasado (2 Re 11:14). Jeremías y Ezequiel extienden el término a conspiraciones proféticas contra el pueblo de Dios (Jer 11:9; Ez 22:25). Isaías advierte contra llamar ''conspiración'' a toda amenaza (Is 8:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7197a', 'spa', 'Recoger o juntar rastrojo, leña o palos — verbo denominativo en Piel que describe la labor servil de forrajear.', 'Verbo denominativo en Piel derivado de qash (''rastrojo''), que describe la laboriosa tarea de recoger palos, rastrojo o paja, típicamente por personas en circunstancias extremas. En Éxodo 5:7-12, la crueldad de Faraón obliga a los israelitas a dispersarse por Egipto recogiendo rastrojo para fabricar ladrillos, escena que epitomiza la servidumbre opresiva. En Números 15:32-33, el hombre que recoge leña en sábado se convierte en caso de prueba para la ley sabática. La viuda de Sarepta, recogiendo dos palos para preparar una última comida antes de morir (1 Re 17:10, 12), presenta quizá la imagen más conmovedora: la supervivencia reducida a la mínima unidad posible de combustible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7198', 'spa', 'Arco: arma para disparar flechas en la guerra o la caza; también el arco iris como señal del pacto de Dios en el cielo.', 'Arco: arma para disparar flechas en la guerra o la caza; también el arco iris como señal del pacto de Dios en el cielo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7200', 'spa', 'Ver, percibir, mirar; (Nifal) aparecer, ser visto; (Hifil) mostrar; (Hofal) ser mostrado; como participio, vidente o profeta', 'Uno de los verbos más frecuentes de la Biblia Hebrea, רָאָה recorre el arco completo desde la vista física hasta la percepción espiritual y la revelación divina. En Qal significa ver o percibir — ya sea Agar viendo un pozo o Dios viendo que la luz era buena (Gn 1:4). El Nifal expresa aparecer o hacerse visible, como cuando YHWH se apareció a Abram (Gn 12:7). El Hifil vuelve el verbo causativo — mostrar algo a alguien —, mientras el Hofal marca el pasivo de ese causativo: ''ser mostrado''. El participio רֹאֶה se convirtió en título para el vidente profético (1 S 9:9), tendiendo un puente entre la vista física y la visión espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7203a', 'spa', 'vidente, el que ve (título arcaico para un profeta)', 'Un título antiguo para el profeta, que el propio narrador bíblico marca como arcaísmo en 1 Samuel 9:9: ''al que hoy se llama profeta, antiguamente se le llamaba vidente.'' Las cinco apariciones de esta forma se concentran en el relato de Saúl buscando a Samuel para hallar las burras perdidas de su padre. El término subraya la capacidad visionaria del profeta: la facultad de percibir lo oculto. En Crónicas el título reaparece como arcaísmo deliberado que honra la época de Samuel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7205', 'spa', 'Rubén — ''¡he aquí, un hijo!''; primogénito de Jacob con Lea, y la tribu israelita asentada en Transjordania.', 'Rubén — ''¡he aquí, un hijo!''; primogénito de Jacob con Lea, y la tribu israelita asentada en Transjordania.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7206', 'spa', 'Rubenita — miembro o descendiente de la tribu de Rubén, hijo primogénito de Israel. Este adjetivo gentilicio identifica a personas pertenecientes a la', 'Rubenita — miembro o descendiente de la tribu de Rubén, hijo primogénito de Israel. Este adjetivo gentilicio identifica a personas pertenecientes a la tribu de Rubén, primogénito de Jacob. Los rubenitas recibieron su asignación territorial al este del Jordán en la meseta transjordana (Dt 3:12, 16; Jos 13:8). Aparecen regularmente junto a los gaditas y la media tribu de Manasés como las tres tribus transjordanas que cruzaron el Jordán armadas para ayudar a conquistar Canaán (Jos 1:12; 22:1). El territorio rubenita cayó posteriormente ante las incursiones moabitas y asirias (2 Re 10:33; 1 Cr 5:26). El término aparece con el artículo como sustantivo colectivo o sin él para individuos (1 Cr 11:42).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7210', 'spa', 'visión, vista; apariencia; espectáculo', 'Sustantivo derivado de la raíz ''ver'' que abarca tres significados emparentados. En Génesis 16:13, Agar nombra a Dios ''El Roi'', el Dios que ve, maravillada de haber visto al que la ve. En 1 Samuel 16:12 describe la apariencia gallarda de David. Job 33:21 lo emplea para la pérdida de aspecto saludable durante la enfermedad, mientras que Nahúm 3:6 pinta a Nínive convertida en espectáculo de escarmiento. La palabra transita del acto divino de ver a lo que se ve, y finalmente a lo que se exhibe ante la mirada ajena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7211', 'spa', 'Reaias (nombre propio teofórico, ''Yahveh ha visto'')', 'Este nombre teofórico, que significa ''Yahveh ha visto'', identifica a tres individuos distintos del periodo postexílico o tardío: un judahita, un rubenita y un jefe de familia entre los que regresaron del exilio. El nombre sigue el patrón hebreo común de invocar la observación o el cuidado divino, combinando רָאָה (''ver'') con el elemento teofórico יָה. Las variaciones textuales y las diversas transliteraciones de la Septuaginta (Ραδα, Ρεια, Ρηχα, Ραια) sugieren cierta fluidez en la transmisión manuscrita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7214', 'spa', 'Toro salvaje, uro (Bos primigenius); poderoso bóvido salvaje que simboliza fuerza indomable.', 'El re''em es el ya extinto toro salvaje o uro, un bóvido de gran tamaño cuyos cuernos y ferocidad lo convirtieron en potente símbolo de fuerza en el antiguo Israel. Números 23:22 y 24:8 comparan el poder de Dios al liberar a Israel con los cuernos de un re''em. Deuteronomio 33:17 equipara la fuerza de José con un toro primogénito de cuernos de uro. Job 39:9-10 pregunta retóricamente si alguien puede domesticarlo. La traducción monokerōs (''unicornio'') de la Septuaginta es una célebre confusión que perduró a través de la Vulgata. El referente real es el uro, no el búfalo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7216', 'spa', 'Ramot (topónimo, ''alturas'')', 'Este topónimo, que significa ''alturas'' o ''lugares elevados'', designa principalmente a Ramot de Galaad, una importante ciudad levítica y ciudad de refugio al este del Jordán. El sitio tuvo gran importancia estratégica, siendo disputado entre Israel y Aram, y figuró prominentemente en las guerras de Acab y en la unción de Jehú. Las variaciones textuales (רָמֹת, רָאמוֹת, רָאמֹת) reflejan diferencias dialectales o de los escribas. Su forma plural concuerda con el terreno elevado de la región de Galaad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7217', 'spa', 'Cognado arameo del hebreo rosh, este vocablo aparece casi exclusivamente en Daniel y Esdras. Con mayor frecuencia significa simplemente la cabeza físi', 'Cognado arameo del hebreo rosh, este vocablo aparece casi exclusivamente en Daniel y Esdras. Con mayor frecuencia significa simplemente la cabeza física — de la estatua de Nabucodonosor (Dan 2:32), del Anciano de Días (Dan 7:9), o de una bestia de cuatro cabezas (Dan 7:6). Sin embargo, también funciona como sede de las visiones nocturnas (''las visiones de tu cabeza sobre tu cama'', Dan 2:28). En Esdras 5:10 se desplaza hacia ''jefe, líder''. En Daniel 7:1 alcanza su registro más abstracto: el ''resumen'' o punto principal de un asunto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7218a', 'spa', 'Cabeza (parte del cuerpo); jefe o líder; cima o cumbre; compañía militar; principio; lo más selecto; suma censal.', 'Uno de los sustantivos más frecuentes de la Biblia hebrea, esta palabra designa fundamentalmente la cabeza física de una persona o animal, pero se ramifica en un abanico semántico notablemente amplio. Dado que la cabeza es la parte más alta, prominente y principal del cuerpo, se extiende con naturalidad a significar la cima de una montaña, el jefe de una tribu, el principio de un período e incluso la suma total de un censo. Estas extensiones metafóricas son antiguas, atestiguadas en toda la familia semítica — desde el acadio reshu hasta el árabe ra''s y el etiópico re''s — y cada tradición de traducción refleja la ramificación: el español distingue cabeza de cima y principio, mientras que el coreano separa meori (cabeza) de udumeori (líder) y kkokdaegi (cumbre).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7218b', 'spa', 'Ros, nombre étnico o geográfico (posiblemente ''principal'' como título)', 'Ros aparece en la profecía de Ezequiel contra Gog como una designación étnica o posiblemente como el título ''principal.'' La frase ''príncipe de Ros, Mesec y Tubal'' podría significar ''príncipe principal de Mesec y Tubal'' o identificar a Ros como un grupo étnico separado junto con Mesec y Tubal. La mayoría de las traducciones antiguas (incluyendo la Septuaginta ''Ρως'') lo tratan como nombre propio de una nación no identificada de otra manera, aunque algunos intérpretes prefieren leerlo como la palabra hebrea para ''cabeza/principal.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7219', 'spa', 'Planta amarga y venenosa; por extension veneno, ponzona o hiel -- siempre con sentido figurado de amargura o juicio', 'Designa una planta toxica o el veneno extraido de ella, empleado sistematicamente en las Escrituras como metafora del juicio amargo, la justicia corrompida o la ira divina. Deuteronomio 29:18 advierte contra una raiz que produce ''veneno y ajenjo'', mientras que Amos 6:12 acusa a Israel de convertir la justicia ''en veneno''. La combinacion con ajenjo (la''anah) en Lamentaciones 3:19 y Jeremias 9:15 crea una de las imagenes mas vividas de angustia en toda la Biblia. Los terminos espanoles ''veneno'' y ''hiel'' abarcan el espectro desde la toxina letal hasta el sabor amargo. Una aparicion (Job 20:16) puede reflejar confusion con el homonimo rosh que significa ''cabeza''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7223', 'spa', 'Primero, anterior, principal; como adjetivo ordinal, temporal o sustantivado: las cosas anteriores, los antepasados, el principio.', 'Derivado de la raíz r-''-sh (''cabeza''), este adjetivo va desde la simple numeración ordinal (''el primer mes,'' Éx 12:15) hasta el teológicamente denso ''las cosas primeras'' de la profecía isaiana (Is 41:22; 43:18). Puede mirar hacia atrás, a los antepasados y generaciones anteriores (Lv 26:45; Dt 4:32), o funcionar como adverbio con el sentido de ''al principio, en el comienzo.'' La construcción comparativa con kaph — ''como al principio'' — lleva una nota de restauración, un anhelo de retorno al estado original (Dt 9:18; Is 1:26). El árabe awwal y el coreano cheot-beonjjae confirman el doble alcance temporal-ordinal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7225', 'spa', 'Principio, origen; primicias o primera porción; lo principal o lo más escogido de algo.', 'Principio, origen; primicias o primera porción; lo principal o lo más escogido de algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7227a', 'spa', 'Mucho, muchos, grande — adjetivo que expresa cantidad (numeroso), cualidad (poderoso, intenso) o suficiencia (bastante).', 'Con más de 400 apariciones, este flexible adjetivo denota primordialmente grandes cantidades (''mucha gente,'' ''mucha riqueza''), pero se extiende con naturalidad a la grandeza cualitativa (''gran maldad,'' ''poder poderoso''). En formas de estado constructo expresa abundancia (''abundante en misericordia,'' ''rico en bondad''), y en contextos exclamativos simplemente significa ''¡basta!'' La evidencia multilingüe — árabe كَثِير, coreano 많은, suajili -engi, hindi बहुत — confirma que la raíz abarca desde la pluralidad numérica hasta la magnitud evaluativa. Ocasionalmente funciona como adverbio (''grandemente,'' ''largo tiempo'') o como sustantivo (''abundancia,'' ''jefe'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7227b', 'spa', 'jefe, capitán — título de alto rango en la administración cortesana babilónica y asiria', 'jefe, capitán — título de alto rango en la administración cortesana babilónica y asiria');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7229', 'spa', 'Adjetivo arameo que significa ''grande'' o ''enorme'', que aparece exclusivamente en Daniel y Esdras. Describe la enorme estatua del sueño de Nabucodonoso', 'Adjetivo arameo que significa ''grande'' o ''enorme'', que aparece exclusivamente en Daniel y Esdras. Describe la enorme estatua del sueño de Nabucodonosor (Dan 2:31), el gran mar (Dan 7:2), y festines e insignias impresionantes. Cuando se usa en cadenas constructas, funciona como título que significa ''jefe'' o ''funcionario principal'', como en ''jefe de los verdugos'' (Dan 2:14) y ''jefe de los magos'' (Dan 4:6). El sentido adjetival se traduce directamente como ''grande'', mientras que el uso titular emerge claramente de expresiones como ''jefe de'' en las traducciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7230', 'spa', 'Multitud, abundancia o grandeza; forma nominal de la raíz ר-ב-ב que expresa gran cantidad, magnitud impresionante o funciona como cuantificador.', 'El sustantivo רֹב es la forma estándar del hebreo para decir ''mucho'' o ''una multitud,'' ya sea contando personas, midiendo cosas o expresando pura magnitud. Con 149 apariciones se encuentra en todos los géneros: promesas patriarcales de descendencia innumerable (Gn 16:10), acusaciones proféticas por los muchos pecados de Israel (Is 1:11), reflexiones sapienciales sobre la ''multitud de palabras'' (Pr 10:19) y declaraciones cósmicas sobre el poder abundante de Dios (Sal 33:16-17). La evidencia interlingüística revela distinciones sutiles que el español puede captar: abundancia (cantidad) frente a grandeza (magnitud). Ocasionalmente funciona como puro cuantificador (''muchos días,'' Ecl 11:1) o incluso verbalmente (''ser abundante,'' Dt 7:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7231', 'spa', 'Ser o llegar a ser muchos, numerosos, multiplicarse (Qal); ser producido por decenas de miles (participio Pual). El verbo ravav expresa un aumento num', 'Ser o llegar a ser muchos, numerosos, multiplicarse (Qal); ser producido por decenas de miles (participio Pual). El verbo ravav expresa un aumento numerico puro: cosas que se multiplican, personas que crecen en numero, problemas que se acumulan. Es el motor verbal detras del adjetivo rav (''muchos, grande'') y comparte raiz con revavah (''diez mil''). En los Salmos da voz tanto al lamento como a la alabanza: ''Oh SENOR, cuantos son mis enemigos!'' (Sal 3:1) y ''muchos dicen: quien nos mostrara el bien?'' (Sal 4:7). Genesis 6:1 lo emplea para narrar la multiplicacion de la humanidad antes del diluvio. El participio Pual en Salmo 144:13 ofrece una imagen agricola rara y vivida: rebanos ''produciendo por decenas de miles'' en los pastizales, donde la conexion del verbo con revavah sale a la superficie de forma explicita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7233', 'spa', 'Miríada o diez mil; usado tanto como numeral específico como expresión de multitud innumerable. Este sustantivo femenino se mueve entre la aritmética ', 'Miríada o diez mil; usado tanto como numeral específico como expresión de multitud innumerable. Este sustantivo femenino se mueve entre la aritmética precisa y la grandeza retórica. Cuando la familia de Rebeca la bendice para que sea ''millares de miríadas'' (Gn 24:60), la palabra evoca abundancia incontable. Cuando Levítico 26:8 dice que cinco perseguirán a cien y cien pondrán en fuga a diez mil, el número es exacto y comparativo. La palabra aparece en algunos de los poemas más triunfantes de las Escrituras, desde la bendición de Moisés (Dt 33:2, 17) hasta los cantos de victoria de David (1 Sam 18:7-8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7235a', 'spa', 'Ser o llegar a ser muchos, multiplicar(se), aumentar; (Hifil) hacer multiplicar; (adverbialmente) mucho, grandemente, en extremo.', 'El verbo hebreo de la abundancia y el aumento, ancla del mandato creacional ''fructificad y multiplicaos'' (Gn 1:22, 28) y reverberante a través de promesas patriarcales, narrativas demográficas y reflexiones sapienciales. Su raíz Qal describe el crecimiento orgánico — las cosas volviéndose numerosas por sí mismas — mientras que su causativo Hifil atribuye la multiplicación a un agente divino o humano. Notablemente, el infinitivo absoluto Hifil se gramaticalizó en un adverbio puro que significa ''mucho'' o ''en extremo'' (Gn 15:1), un proceso que el árabe refleja con kathiran. El Piel se extiende a la crianza de hijos (Ez 19:2) y la magnificación territorial (2 Sam 22:36), revelando que la raíz abarca la grandeza cualitativa junto al aumento cuantitativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7236', 'spa', 'Crecer, hacerse grande (Qal intransitivo); engrandecer, magnificar, exaltar (Piel causativo) — arameo.', 'Este verbo arameo, cognado del hebreo común rabah, aparece exclusivamente en el libro de Daniel. En su forma Qal describe un crecimiento orgánico, a menudo espectacular: el gran árbol del sueño de Nabucodonosor que ''creció y se hizo fuerte'' hasta alcanzar los cielos (Dan 4:11, 20), y el cabello del rey que ''creció largo'' como plumas de águila durante su humillación (Dan 4:33). La única aparición en Piel pasa a la acción causativa: el rey ''engrandeció a Daniel'' con honores y regalos (Dan 2:48). El español distingue con nitidez: ''crecer'' para el crecimiento intransitivo y ''engrandecer'' para la magnificación activa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7237', 'spa', 'Rabba -- ''la gran ciudad,'' capital de Amon (actual Aman, Jordania); tambien una ciudad en Juda. Con el significado de ''grande'' o ''populosa,'' Rabba (רַ', 'Rabba -- ''la gran ciudad,'' capital de Amon (actual Aman, Jordania); tambien una ciudad en Juda. Con el significado de ''grande'' o ''populosa,'' Rabba (רַבָּה) designa tipicamente la capital amonita, presentada frecuentemente en su forma completa ''Rabba de los hijos de Amon'' (רַבַּת בְּנֵי עַמּוֹן). Es la ciudad donde se guardaba la enorme cama de hierro de Og (Dt 3:11), donde el general de David, Joab, puso sitio durante la crisis de Betsabe (2 Sam 11:1; 12:26-29), y contra la cual los profetas pronunciaron juicio (Jer 49:2-3; Amos 1:14). Conocida como Filadelfia en el periodo helenistico, sobrevive como la moderna Aman. Una segunda Rabba, menos conocida, aparece entre las ciudades de Juda (Jos 15:60).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7238', 'spa', 'grandeza, majestad (arameo; del poder y esplendor reales)', 'Sustantivo arameo que aparece exclusivamente en Daniel, siempre vinculado a la majestad real. Describe la grandeza restituida a Nabucodonosor tras su humillación (Dn 4:22, 36), el honor soberano que Dios le otorgó (Dn 5:18, 19) y la grandeza eterna del reino entregado a los santos (Dn 7:27). El vocablo connota tanto autoridad política como esplendor visible. El español ''grandeza'' capta con exactitud ese doble sentido de magnitud y magnificencia que caracteriza al término en su contexto cortesano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7239', 'spa', 'Diez mil, miriada -- numero redondo grande para contar personas, bienes o fuerzas; forma tardia de influencia aramea', 'El sustantivo רִבּוֹ (ribbo) es un sinonimo tardio de influencia aramea de רְבָבָה que significa ''diez mil'' o ''miriada'', y aparece principalmente en la literatura posexilica. Los exiliados que regresaron sumaban 42.360 (Esdras 2:64; Nehemias 7:66), y las ofrendas para el tesoro del templo se contabilizaban en unidades de ribbo (1 Cr 29:7; Esd 2:69; Neh 7:70-72). Daniel usa el plural para designar fuerzas militares apocalipticas que derriban miriadas (Dn 11:12). La forma dual ribbotayim en el Salmo 68:18 significa ''dos veces diez mil'', es decir, veinte mil carros de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7240', 'spa', 'miríada, diez mil (arameo)', 'Este término arameo para ''miríada'' o ''diez mil'' aparece en la visión del trono de Daniel describiendo a los incontables asistentes celestiales. El texto en realidad lo usa tres veces en una sola frase, con lecturas tanto Ketiv como Qere intentando expresar la magnitud incomprensible: ''mil millares le servían, y diez mil veces diez mil estaban delante de Él.'' La repetición y las formas variantes transmiten multitudes innumerables más allá del cálculo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7241', 'spa', 'Aguaceros copiosos o lluvia abundante, siempre en plural; usado literal y figuradamente de bendición e influencia.', 'Apareciendo siempre en plural, revivim designa aguaceros copiosos y abundantes — el tipo de lluvia torrencial que hace fértil la tierra y prosperar los cultivos. La palabra opera en dos registros simultáneamente: lluvia literal como señal del favor de Dios (Sal 65:10; Jer 3:3; 14:22), y aguaceros metafóricos que representan una influencia transformadora. El cántico de despedida de Moisés compara su enseñanza con lluvias sobre la hierba nueva (Deut 32:2), y Miqueas contempla al remanente de Jacob cayendo entre las naciones ''como aguaceros sobre la vegetación'' — una fuerza divina silenciosa e irresistible (Miq 5:6). El Salmo 72:6 retrata al rey ideal descendiendo como lluvia sobre hierba recién segada, refrescando y renovando.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7243', 'spa', 'Cuarto (numeral ordinal); una cuarta parte o un cuarto (fracción); raramente, cuadrado (geométrico).', 'Cuarto (numeral ordinal); una cuarta parte o un cuarto (fracción); raramente, cuadrado (geométrico).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7244', 'spa', 'Cuarto (numeral ordinal arameo); usado en Daniel para el cuarto reino, la cuarta figura en el horno y la cuarta bestia.', 'El numeral ordinal arameo ''cuarto'', que aparece exclusivamente en las visiones y narraciones apocalípticas de Daniel. Designa el cuarto reino en el sueño de la estatua de Nabucodonosor, fuerte como el hierro y que tritura a todos los demás (Dn 2:40). Identifica a la misteriosa cuarta figura que camina en el horno de fuego, cuya apariencia era ''semejante a un hijo de los dioses'' (Dn 3:25). Y nombra a la espantosa cuarta bestia de la visión nocturna, ''terrible y extraordinariamente fuerte'', con dientes de hierro (Dn 7:7, 19, 23). En cada caso, lo ''cuarto'' conlleva un peso de misterio y poder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7246', 'spa', 'mezclar, revolver (masa); bien mezclado, revuelto (participio Hofal)', 'Este verbo describe la mezcla o el batido minucioso de harina fina para ofrendas de grano, apareciendo solo como participio Hofal en contextos sacrificiales técnicos. El término indica masa que ha sido bien trabajada—mezclada con aceite y batida hasta alcanzar la consistencia apropiada. Aparece exclusivamente en la legislación levítica y Crónicas, funcionando como terminología cúltica para la preparación correcta de las ofrendas de cereal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7247', 'spa', 'Ribla, ciudad en la tierra de Hamat junto al Orontes, usada como base militar por Egipto y Babilonia', 'Ciudad estrategica junto al rio Orontes en la tierra de Hamat, Ribla sirvio como puesto de mando avanzado para los grandes imperios que dominaron las ultimas decadas de Israel. El faraon Necao aprisiono alli a Joacaz e impuso tributo a Juda (2 R 23:33). Posteriormente, Nabucodonosor establecio en Ribla su base para dirigir el asedio de Jerusalen, y fue alli donde los hijos de Sedequias fueron ejecutados ante sus ojos antes de que el mismo fuera cegado (2 R 25:6-7; Jer 52:9-10). La ciudad tambien aparece como punto de demarcacion de la tierra prometida (Nm 34:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7248', 'spa', 'Rab-mag, jefe de los magos o jefe de los adivinos (título babilónico)', 'Rab-mag era un título oficial babilónico que significaba ''jefe de los magos'' o ''jefe de los adivinos'', que aparece en el relato de Jeremías sobre la caída de Jerusalén. El término es un préstamo del acadio ''rab maḫḫû'' (jefe de los adivinos), identificando a un miembro de alto rango de la corte de Nabucodonosor que participó en la conquista. Este oficial pertenecía a la clase de sabios, adivinos y magos que asesoraban a los reyes babilónicos—un grupo al que Daniel se uniría posteriormente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7249', 'spa', 'Jefe, maestro; titulo babilonico-asirio que forma designaciones compuestas de cargos oficiales (Rab-saris, Rab-mag, Rab-saces)', 'Prestamo del acadio que significa ''jefe'' o ''maestro'', empleado en hebreo exclusivamente como primer elemento de titulos compuestos de la corte babilonica. Aparece en expresiones como Rab-saris (jefe de eunucos), Rab-mag (jefe de magos) y Rab-saces (jefe de coperos), todos referidos a oficiales de alto rango del imperio. La palabra surge unicamente en narraciones que involucran encuentros de los estados asirio y babilonico con Israel y Juda, lo que la marca como un prestamo tecnico del vocabulario administrativo extranjero y no como una palabra hebrea nativa para el liderazgo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7250', 'spa', 'acostarse, yacer extendido; aparear (de animales)', 'Este verbo describe el acostarse o estar extendido, con aplicaciones tanto literales como específicas. El Salmo 139 lo usa para el descanso pacífico (''mi acostarme''). Levítico lo emplea técnicamente para el apareamiento animal, particularmente en leyes que prohíben la bestialidad y el cruce de especies. La raíz es un cognado arameo del hebreo ''rabats'' (acostarse), pero desarrolló un sentido especializado en contextos legales para la cópula.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7251', 'spa', 'Hacer cuadrado, ser de cuatro lados -- dar forma de cuatro lados iguales y angulos rectos, especialmente al mobiliario sagrado', 'El verbo רָבַע (raba'') significa hacer cuadrado o de cuatro lados, y aparece casi exclusivamente como participio pasivo (רָבוּעַ) describiendo la forma de objetos sagrados del tabernaculo y el templo. El altar del holocausto es ''cuadrado'': cinco codos por cinco codos (Ex 27:1; 38:1). El altar del incienso es igualmente ''cuadrado'': un codo por un codo (Ex 30:2). El pectoral del sumo sacerdote se pliega en forma ''cuadrada'': un palmo por un palmo (Ex 28:16). El atrio del templo visionario de Ezequiel es ''cuadrado'' (Ez 40:47; 43:16; 45:2). La aplicacion sistematica a la arquitectura sagrada sugiere que la precision geometrica era parte integral de la santidad de los espacios de culto de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7253', 'spa', 'Cuarta parte o cuarto (de una medida); también, uno de los cuatro lados o flancos de una estructura', 'Derivado de la raíz que significa ''cuatro'', este sustantivo cumple dos funciones claras en las Escrituras. Como término fraccional, designa un cuarto: la cuarta parte de un hin de vino (Éx 29:40) o un cuarto de siclo de plata (1 Sam 9:8). En la arquitectura visionaria de Ezequiel, sin embargo, adquiere un sentido espacial: los cuatro lados del hogar del altar (Ezeq 43:16-17) o los cuatro flancos de los seres vivientes y sus ruedas (Ezeq 1:8, 17; 10:11). El uso fraccional y el espacial son igualmente prominentes en el texto bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7256', 'spa', 'cuarta generación (en contexto genealógico)', 'Este adjetivo designa a los miembros de la cuarta generación en una serie genealógica, y aparece exclusivamente en la fórmula ''sobre la tercera y sobre la cuarta generación'' referida a la visitación divina del pecado ancestral. La expresión limita el castigo intergeneracional a un lapso temporal definido, contrastando con el amor pactual ilimitado que se extiende a miles de generaciones. Su uso es estrictamente formulaico dentro del contexto del Decálogo y las renovaciones del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7257', 'spa', 'Echarse, tenderse o agacharse en reposo; causativamente, hacer que se eche o asentar firmemente en su lugar', 'Echarse, tenderse o agacharse en reposo; causativamente, hacer que se eche o asentar firmemente en su lugar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7258', 'spa', 'lugar de descanso, guarida, redil', 'Este sustantivo denota un lugar donde se echan o reposan animales o personas, enfatizando descanso, morada o ubicación habitual. Con frecuencia se empareja con ''pasto'' o ''aprisco'', resaltando seguridad y reposo. En la literatura profética y sapiencial puede describir metafóricamente las moradas humanas o el hogar del justo. Su campo semántico abarca desde la guarida animal hasta la imagen teológica de restauración y protección divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7259', 'spa', 'Rebeca — matriarca de Israel, esposa de Isaac, madre de Esaú y Jacob', 'Rebeca — matriarca de Israel, esposa de Isaac, madre de Esaú y Jacob');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7260', 'spa', 'Grande, imponente (arameo); como sustantivo, ''grandes cosas'' o palabras jactanciosas.', 'Adjetivo arameo que aparece exclusivamente en el libro de Daniel, describiendo tamaño, poder y majestuosidad. Un gran banquete (Dan 5:1), grandes bestias que surgen del mar (Dan 7:3, 7) y grandes obsequios otorgados a Daniel (Dan 2:48): la palabra transmite magnitud tanto literal como figurada. Cuando se usa como sustantivo en Daniel 7:8 y 7:20, las ''grandes cosas'' pronunciadas por el cuerno pequeño adquieren un tono ominoso de arrogancia y jactancia. En todas las traducciones, el español ''grandes/grandes cosas'', el francés ''grand/grands'' y el alemán ''Grosse'' capturan uniformemente este rango que va desde la escala impresionante hasta el discurso presuntuoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7261', 'spa', 'Nobles, magnates, señores; título arameo cortesano para altos funcionarios del imperio babilónico-persa.', 'Sustantivo arameo formado por reduplicación de rav (''grande''), que intensifica el significado a ''los más grandes'': nobles o magnates de la corte real. Aparece exclusivamente en Daniel 4-6, describiendo a los cortesanos de Nabucodonosor (Dn 4:36), los mil nobles del banquete de Belsasar (Dn 5:1-3, 9-10, 23) y los funcionarios bajo Darío (Dn 6:17). El término refleja la opulencia y la estructura jerárquica de las cortes imperiales babilónica y persa. La forma reduplicativa en sí misma señala una grandeza enfática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7262', 'spa', 'Rabsaces; título militar asirio que significa ''jefe de los coperos'' o ''oficial principal,'' usado para el enviado de Senaquerib', 'Rabsaces; título militar asirio que significa ''jefe de los coperos'' o ''oficial principal,'' usado para el enviado de Senaquerib');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7264', 'spa', 'Temblar, estremecerse, enfurecerse o agitarse; de la tierra que tiembla, personas que tiemblan de miedo, o personas que se enfurecen; causativo: pertu', 'Temblar, estremecerse, enfurecerse o agitarse; de la tierra que tiembla, personas que tiemblan de miedo, o personas que se enfurecen; causativo: perturbar o provocar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7267', 'spa', 'Agitación, turbación, ira o trueno; abarca la inquietud interior, la ira divina y el estruendo de la voz de Dios.', 'Sustantivo hebreo que abarca el espectro desde la perturbación interior hasta el poder cósmico. En los lamentos de Job describe la turbación y la inquietud incesante que azotan la vida mortal (Job 3:17, 26; 14:1), y en Isaías 14:3 designa la dura servidumbre de la cual Dios concede alivio. En su máxima intensidad denota una ira feroz: el furor tembloroso del caballo de guerra (Job 39:24) o la propia ira de Dios que Habacuc suplica temperar con misericordia (Hab 3:2). En Job 37:2 describe singularmente el rugido atronador de la voz divina, donde el español ''rugido'' y el inglés ''thunder'' capturan ese sonido natural sobrecogedor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7270', 'spa', 'Espiar, explorar una tierra; también calumniar, andar como chismoso', 'Espiar, explorar una tierra; también calumniar, andar como chismoso');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7271', 'spa', 'Pie o pies; usado exclusivamente en las visiones apocalípticas de Daniel sobre la gran estatua y las bestias.', 'Sustantivo arameo que significa ''pie'' o ''pies'', presente únicamente en la literatura visionaria de Daniel. Describe los pies de la gran imagen del sueño de Nabucodonosor, en parte de hierro y en parte de barro (Dan 2:33-42), y los terribles pies de la cuarta bestia que todo lo pisoteaba (Dan 7:4, 7, 19). Las traducciones en español e inglés lo rinden uniformemente como ''pies/feet'', confirmando un solo sentido coherente a lo largo de las ocho ocurrencias. Aunque la palabra es ordinaria en su significado, su contexto exclusivamente apocalíptico le confiere un peso simbólico cargado de intensidad profética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7272', 'spa', 'Pie, pies; por extensión pierna, paso, marcha; idiomáticamente ''a pie'' (peatonal) y ''veces'' (ocasiones).', 'Este es uno de los sustantivos más concretos y corpóreos del hebreo, arraigado firmemente en el pie físico que camina por senderos polvorientos, se posa sobre suelo sagrado y es lavado por un anfitrión generoso. Pero como muchos términos corporales, se extiende hacia un rico territorio figurado. El dual raglayim aparece en escenas de postración, narrativas de viaje y contextos eufemísticos por igual. Combinado con preposiciones, puede describir proximidad (''a los pies de,'' es decir, bajo la autoridad de alguien), modo de viaje (''a pie,'' en oposición a montado), o ritmo y marcha (''al paso del ganado,'' Gn 33:14). Lo más sorprendente es que el plural regalim se desarrolló en un vocablo para contar ''veces'' — como en ''tres regalim,'' las tres fiestas de peregrinación (Éx 23:14) — una metonimia desde los pasos repetidos hasta las ocasiones repetidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7273', 'spa', 'Soldado de a pie, infante -- hombre que va a la batalla a pie, a diferencia de los que luchan en carros o a caballo', 'El sustantivo רַגְלִי (ragli), derivado de רֶגֶל (''pie''), designa a un soldado que combate a pie, es decir, un infante. Aparece en contextos que enfatizan el enorme numero de combatientes de Israel o que los contrastan con guerreros montados. En el Exodo, unos seiscientos mil ''hombres de a pie'' partieron de Egipto (Ex 12:37; Nm 11:21). Israel reune cuatrocientos mil soldados de infanteria contra Benjamin (Jue 20:2), y treinta mil caen ante los filisteos (1 S 4:10). Segundo de Samuel 8:4 y 2 Reyes 13:7 contrastan la infanteria con los carros y los jinetes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7275', 'spa', 'Apedrear, matar a pedradas — ejecución comunal mediante el lanzamiento de piedras según lo prescrito por la ley. Verbo para el acto de arrojar piedras', 'Apedrear, matar a pedradas — ejecución comunal mediante el lanzamiento de piedras según lo prescrito por la ley. Verbo para el acto de arrojar piedras contra una persona, siempre en el contexto de ejecución legalmente prescrita o violencia de turbas amenazada. Casi todas las ocurrencias caen dentro de la legislación pentateuca: el apedreamiento se ordena por blasfemia (Lv 24:14, 16), culto a Moloc (Lv 20:2), nigromancia (Lv 20:27), violación del sábado (Nm 15:35-36) y un hijo rebelde (Dt 21:21). Los usos narrativos son igualmente dramáticos: Acán es apedreado tras su pecado en Jericó (Jos 7:25), Adoram es apedreado por las tribus del norte en revuelta (1 Re 12:18), y la congregación amenaza con apedrear a Moisés y Aarón (Nm 14:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7279', 'spa', 'murmurar, quejarse (rebelemente); calumniar, difamar', 'Este verbo describe murmuración descontenta, ya sea queja rebelde contra la autoridad o susurros maliciosos sobre otros. Deuteronomio y Salmos lo usan para la murmuración de Israel contra Dios en el desierto—quejas bajas y malhumoradas habladas en tiendas en lugar de discurso abierto. Isaías lo extiende a quienes murmuran escépticamente contra la instrucción profética. El participio Nifal en Proverbios significa un calumniador o chismoso que difunde rumores maliciosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7280a', 'spa', 'Agitar o perturbar (el mar); aquietar, calmar; en un instante, de repente (uso adverbial del Hifil)', 'Un verbo compacto que abarca la paradoja del poder divino sobre el mar. En el participio Qal, Dios es ''el que agita el mar para que bramen sus olas'' (Jer 31:35; Isa 51:15), el agitador soberano de las aguas cosmicas. Sin embargo, en Job 26:12 la misma raiz parece significar lo opuesto: ''con su poder aquieto el mar'', el domador de la tormenta cosmica. El Hifil denominativo, derivado del sustantivo rega'' (un momento), produce un sentido adverbial — ''en un abrir y cerrar de ojos'' — usado para la naturaleza fugaz de la mentira (Prov 12:19) y la velocidad instantanea del juicio divino (Jer 49:19; 50:44).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7280b', 'spa', 'Estar en reposo, descansar; en Hifil, dar descanso o establecer firmemente', 'Un verbo que expresa el cese de la agitacion y el logro del reposo o la estabilidad. En el Nifal, comunica el imperativo ''estate quieto'', como en Jer 47:6, donde el profeta ordena a la espada del Senor que vuelva a su vaina y se aquiete. El Hifil lleva tanto un sentido causativo — ''dar descanso a'' (Jer 31:2, de Dios conduciendo a Israel al reposo) — como un significado mas especializado de establecer algo de manera permanente, como en Isa 51:4 donde la justicia de Dios queda ''asentada'' como luz para los pueblos. El cognado arabe raja''a (volver) sugiere que la imagen subyacente es la de retornar a un estado de reposo tras la errancia o la agitacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7281', 'spa', 'Momento, instante; un breve lapso de tiempo, usado frecuentemente de forma adverbial para expresar lo repentino o lo fugaz', 'Momento, instante; un breve lapso de tiempo, usado frecuentemente de forma adverbial para expresar lo repentino o lo fugaz');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7284', 'spa', 'venir en tropel, reunirse tumultuosamente (arameo)', 'Este verbo arameo describe asamblea tumultuosa o agolpamiento urgente, apareciendo en el relato de Daniel sobre la intriga en la corte persa. La forma Hafel indica oficiales apresurándose o amontonándose urgentemente, creando una escena de acción colectiva agitada. Daniel 6 lo usa para los conspiradores que se reunieron en masa ante el rey Darío para exigir la aplicación del decreto inmutable contra Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7286', 'spa', 'someter, abatir, batir (metal en láminas)', 'Este verbo expresa la acción de golpear o martillar, ya sea en el contexto de subyugación militar o de trabajo metalúrgico. El significado raíz de ''abatir'' se extiende a someter enemigos (pisotearlos bajo los pies) y al proceso técnico de batir oro en láminas para recubrimiento. El rango semántico refleja la superposición en el antiguo Cercano Oriente entre el vocabulario marcial y el artesanal, uniendo fuerza destructiva y habilidad creativa en una misma raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7287a', 'spa', 'Gobernar, ejercer dominio; también pisotear o sojuzgar por la fuerza', 'Gobernar, ejercer dominio; también pisotear o sojuzgar por la fuerza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7287b', 'spa', 'raspar, extraer (de horno o cadáver)', 'Este segundo homónimo del más común ''radah'' (gobernar) significa raspar o extraer algo. Jueces 14 lo usa dos veces para Sansón raspando miel del cadáver del león: primero raspándola para sacarla, luego raspándola en sus manos. Algunos eruditos también interpretan Jeremías 5:31 con este sentido: profetas y sacerdotes ''raspan'' ganancias ilícitas del pueblo. El verbo sugiere extraer o remover algo al sacarlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7290', 'spa', 'radam — caer en un sueño profundo y pesado; quedar aturdido en inconsciencia o estupor.', 'Verbo en Nifal que describe el inicio o el estado de un sueño profundo y abrumador que raya en la inconsciencia. Cuando Sísara cayó en un sueño exhausto, Jael le clavó una estaca en la sien (Jue 4:21); cuando Jonás descendió a la bodega del barco, se sumió en un sueño tan profundo que el capitán tuvo que sacudirlo durante la tormenta (Jon 1:5-6). En las visiones de Daniel, la palabra describe un estupor inducido divinamente: caer rostro en tierra, abrumado por el asombro y el pavor (Dan 8:18; 10:9). Proverbios emplea el participio para caracterizar al perezoso que duerme durante la cosecha (Prov 10:5), y el salmista lo utiliza para el sueño de la muerte (Sal 76:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7291', 'spa', 'Perseguir, ir tras, hostigar; también seguir con empeño o buscar afanosamente un objetivo, ideal o persona.', 'Un verbo de movimiento vigoroso que describe el acto de correr tras alguien o algo con la intención de alcanzarlo. En contextos militares representa a ejércitos persiguiendo a enemigos en fuga; en los Salmos se convierte en el clamor del oprimido acosado por sus perseguidores. Sin embargo, la misma palabra puede describir la noble búsqueda de la justicia o la paz (Dt 16:20; Sal 34:14). Los cognados semíticos — árabe radafa, arameo redap y siríaco rdap — preservan esta raíz, subrayando un concepto pansemítico de persecución decidida y enérgica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7292', 'spa', 'Actuar con arrogancia, arremeter contra, abrumar emocionalmente', 'Este verbo expresa una acción turbulenta y agresiva, ya sea un asalto arrogante, una insistencia apremiante hacia alguien, o el acto de abrumar emocionalmente. La raíz se vincula con la idea de irrumpir con fuerza y causar alarma, abarcando desde la confrontación hostil hasta el impacto emocional intenso. Su uso es poco frecuente en las Escrituras, y algunos pasajes presentan incertidumbre textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7293', 'spa', 'Rahab, monstruo marino mítico; nombre simbólico para Egipto', 'Rahab (distinto de la Rahab de Jericó) es un monstruo del caos mítico que representa fuerzas primordiales derrotadas por Dios, y también un epíteto poético para Egipto. En Job, se dice que Dios vence ''a los ayudadores de Rahab'' y traspasa la serpiente huidiza, usando imágenes del combate contra el caos del antiguo Cercano Oriente. Isaías llama a Egipto ''Rahab'' como emblema de poder orgulloso pero impotente: ''Rahab que se queda quieta'', incapaz de ayudar a Israel contra Asiria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7294', 'spa', 'Rahab, monstruo del caos mítico que simboliza la conquista divina sobre fuerzas primordiales', 'Esta instancia de Rahab (idéntica en significado a H7293) aparece en Salmos e Isaías como el monstruo del caos derrotado de la mitología antigua. Salmo 89 celebra que Dios cortó a Rahab en pedazos como quien aplasta al muerto, demostrando soberanía sobre fuerzas caóticas. Salmo 87 lo usa simbólicamente para Egipto. Isaías 51 hace paralelo entre Rahab y ''el dragón'' (tannin), invocando al brazo de Dios que ''traspasó a Rahab'' en tiempos primigenios para actuar nuevamente en la redención del éxodo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7298a', 'spa', 'abrevadero, canal donde beben los animales', 'Este sustantivo designa los abrevaderos o canales donde se acumula agua para dar de beber al ganado. Génesis 30 describe a Jacob manipulando la reproducción de su rebaño colocando varas rayadas en los abrevaderos donde venían a beber y aparearse. Éxodo 2 menciona los abrevaderos donde las hijas de Jetro daban agua al rebaño de su padre antes de la intervención de Moisés. Estos eran elementos esenciales de la vida pastoral, lugares donde los animales se reunían regularmente para beber agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7300', 'spa', 'Vagar sin descanso, deambular libremente', 'Este verbo denota un movimiento errante o inquieto, ya sea un desplazamiento literal o un vagar figurado en sentido espiritual. La raíz sugiere ir y venir sin propósito fijo ni sujeción. Su uso bíblico es limitado y a veces textualmente problemático, pero el sentido fundamental de un movimiento sin ancla se mantiene en todos los contextos donde aparece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7301', 'spa', 'Beber hasta saciarse, estar saturado; en los troncos causativos, satisfacer, empapar o regar abundantemente. Un verbo rico de profunda satisfaccion, ר', 'Beber hasta saciarse, estar saturado; en los troncos causativos, satisfacer, empapar o regar abundantemente. Un verbo rico de profunda satisfaccion, רָוָה pinta un cuadro de saturacion completa: ya sea una tierra reseca empapada por la lluvia (Sal 65:10), un alma colmada hasta rebosar por la bondad de Dios (Jer 31:14), o amantes embriagados de afecto (Pr 7:18). La palabra transita fluidamente entre lo fisico y lo espiritual: Isaias 55:10 la usa para la lluvia que empapa la tierra, mientras que el Salmo 36:8 aplica la misma imagen al banquete de la abundancia de la casa de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7302', 'spa', 'regado, saturado, bien irrigado', 'Este adjetivo describe tierra o vegetación que está bien regada y floreciente, usado en símiles positivos y contrastes proverbiales. Los profetas comparan la comunidad bendecida con un ''jardín regado'', enfatizando abundancia y vitalidad versus sequía. Deuteronomio 29 lo usa en una advertencia proverbial sobre destruir juntos ''lo regado y lo sediento'': todo desde lo floreciente hasta lo reseco, quizás significando al inocente con el culpable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7304', 'spa', 'ser ancho, espacioso; hallar alivio, tener espacio para respirar', 'Este verbo describe amplitud espacial y, figuradamente, el alivio psicológico que viene al tener espacio para respirar. Cuando la angustia de Saúl se levantó después que David tocó el arpa, ''hubo alivio para él''—literalmente, se volvió espacioso para él. Job anhela hablar para que ''tenga alivio'', usando la misma imagen de constricción dando paso a espacio para respirar. Jeremías lo aplica literalmente a las habitaciones espaciosas y bien acondicionadas de un palacio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7306', 'spa', 'Oler, percibir un aroma; metafóricamente, deleitarse en algo o saborearlo', 'El verbo denominativo Hifil רִיחַ significa oler o percibir un aroma, derivado del sustantivo רֵיחַ (''fragancia, aroma''). Su uso más memorable aparece en Gn 8:21, donde el SEÑOR ''olió el aroma agradable'' del sacrificio de Noé — un momento sorprendentemente antropomórfico que resuena en todo el antiguo Cercano Oriente. El verbo puede describir percepción sensorial literal (Isaac oliendo las vestiduras de Jacob en Gn 27:27, los ídolos que no pueden oler en Dt 4:28) y se extiende metafóricamente a ''deleitarse en'' o ''saborear'', como en la visión de Isaías del Mesías cuyo deleite (הֲרִיחוֹ) está en el temor del SEÑOR (Is 11:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7307', 'spa', 'Viento, aliento, espíritu; el Espíritu de Dios; disposición o ánimo humano; punto cardinal; seres espirituales.', 'Pocas palabras hebreas rivalizan con רוּחַ en amplitud semántica y hondura teológica. Desde el viento concreto que parte el mar Rojo (Éx 14:21) hasta el Espíritu de Dios sobre las aguas primordiales (Gn 1:2), este sustantivo femenino abarca lo físico y lo numinoso. Su cognado árabe se divide entre رِيح (viento) y رُوح (espíritu), escisión que el hebreo rehúsa: la misma palabra sirve para el viento del este que destruye naves (Sal 48:7), el espíritu abatido del oprimido (Éx 6:9) y el Espíritu divino que capacita a Bezalel (Éx 31:3). Esta negativa a separar aliento de espíritu es una afirmación teológica sobre la unidad de la vitalidad creada y divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7308', 'spa', 'Espíritu o viento (arameo); el espíritu animador divino o humano, o viento meteorológico, en Daniel', 'El sustantivo arameo רוּחַ aparece exclusivamente en el libro de Daniel, reflejando su cognado hebreo pero dentro del contexto teológico y visionario distintivo de las narraciones cortesanas arameas y las visiones apocalípticas. Como ''espíritu'', describe tanto el espíritu divino que habita en Daniel — ''el espíritu de los dioses santos'' (Dn 4:8-9, 5:11-14) — como el espíritu turbado del propio vidente (Dn 7:15). Como ''viento'', aparece en dos escenas visionarias dramáticas: el viento que dispersa la estatua despedazada de Nabucodonosor (Dn 2:35) y los cuatro vientos del cielo que agitan el gran mar (Dn 7:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7311a', 'spa', 'Ser alto, exaltado; levantar, alzar (física o figuradamente); ensalzar, enaltecer (a Dios o a una persona); contribuir (una ofrenda).', 'Este verbo, con 190 apariciones, recorre un arco semántico notable desde el acto físico de levantar hasta la exaltación metafórica. Describe alzar la mano para jurar (Gn 14:22), montañas que son altas (Dt 1:28), sacerdotes que elevan porciones como ofrenda mecida (Lv 2:9), salmistas que ensalzan el nombre de Dios (Éx 15:2), reyes exaltados al trono (1 S 2:10) y orgullosos cuyos ojos se elevan con arrogancia (Pr 6:17). Las conjugaciones distinguen el estado intransitivo (Qal: ''ser alto, elevarse''), la alabanza intensiva (Piel: ''ensalzar, magnificar'') y la elevación causativa (Hifil: ''levantar, exaltar, quitar'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7312', 'spa', 'Altura, elevacion; especialmente altivez y arrogante autoexaltacion', 'Sustantivo derivado de la raiz rum (ser alto), que abarca tanto el concepto fisico de altura como el concepto moral de orgullo. En Prov 25:3, denota la altura espacial literal — ''los cielos por la altura'' — emparejada con la profundidad como cosas inescrutables, analogas al corazon inescrutable de un rey. Con mucha mayor frecuencia, sin embargo, nombra el pecado de la altivez: Isa 2:11 y 2:17 lo emparejan con la soberbia humana que sera humillada en el Dia del Senor. El aleman ''Erhabenheit'' (sublimidad) capta ambas dimensiones, mientras que el espanol ''altivez'' y ''soberbia'' apuntan directamente a la falta moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7313', 'spa', 'Levantarse, ser exaltado, ensalzar (arameo)', 'Este verbo arameo, que aparece exclusivamente en Daniel, expresa elevación o exaltación: ya sea la autoexaltación por orgullo, el ser elevado por otro, o el ofrecer alabanza. Su rango semántico es paralelo al hebreo רוּם, abarcando tanto el alzarse físico como la elevación metafórica de estatus o espíritu. Todas sus apariciones se relacionan con el orgullo, la soberanía divina o la adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7314', 'spa', 'altura (arameo; de estructuras y árboles visionarios)', 'Sustantivo arameo que designa la altura física, empleado en Daniel y Esdras para dimensiones verticales imponentes. Esdras 6:3 especifica la altura del templo reconstruido en sesenta codos. Daniel 3:1 registra la imagen de oro de Nabucodonosor con sesenta codos de alto. Las tres apariciones restantes (Dn 4:10, 11, 20) describen el gran árbol del sueño de Nabucodonosor cuya altura alcanzaba el cielo, simbolizando el dominio descollante pero vulnerable del rey. La palabra evoca invariablemente el asombro ante estructuras que aspiran hacia lo alto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7321', 'spa', 'Gritar, levantar un clamor; aclamar con gozo en la adoración, lanzar un grito de guerra, tocar alarma con trompeta', 'Gritar, levantar un clamor; aclamar con gozo en la adoración, lanzar un grito de guerra, tocar alarma con trompeta');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7323', 'spa', 'Correr, moverse velozmente; como participio: corredor, guardia real (cuerpo de escolta); causativo: hacer correr, perseguir.', 'Verbo de movimiento vigoroso que transmite la energía de correr hacia un objetivo o huir de un peligro. Abraham corrió al encuentro de los tres visitantes en Mamré (Gn 18:2, 7), y los mensajeros corrían entre campos de batalla y tronos. El participio הָרָצִים se convirtió en término fijo para la guardia real que servía como centinelas y verdugos bajo los reyes de Israel y Judá (1 R 14:27-28; 2 R 10:25). En el período persa, la misma forma designaba a correos reales del imperio (Est 3:13-15). El Hifil causativo extiende la raíz a ''hacer correr'': perseguir o llevar con urgencia, como cuando sacaron a José de la prisión ante Faraón (Gn 41:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7324', 'spa', 'Vaciar, derramar, desenvainar (una espada) o movilizar (tropas) — expresando extracción o derramamiento enérgico en sentido tanto literal como figurad', 'Vaciar, derramar, desenvainar (una espada) o movilizar (tropas) — expresando extracción o derramamiento enérgico en sentido tanto literal como figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7326', 'spa', 'Ser pobre, estar en necesidad; como participio: persona pobre o indigente; también fingir pobreza', 'Ser pobre, estar en necesidad; como participio: persona pobre o indigente; también fingir pobreza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7327', 'spa', 'Rut — mujer moabita que se aferró a su suegra Noemí y se convirtió en antepasada del rey David', 'Rut (רוּת) es la mujer moabita cuya historia se narra en el libro que lleva su nombre. Tras la muerte de su esposo, se negó a abandonar a su suegra Noemí, declarando: ''Donde tú vayas, yo iré; tu pueblo será mi pueblo, y tu Dios mi Dios'' (Rt 1:16). Siguió a Noemí a Belén, espigó en los campos de Booz (Rt 2:2-8), y mediante la costumbre del levirato se convirtió en su esposa. Su hijo Obed fue abuelo de David (Rt 4:13-17), situando a Rut en el linaje mesiánico. Su historia narra con fuerza la lealtad, la providencia y la inclusión de una extranjera en la comunidad del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7328', 'spa', 'Secreto o misterio divino, revelado mediante visión profética o interpretación (arameo, usado solo en Daniel).', 'Préstamo arameo de origen persa, empleado exclusivamente en el libro de Daniel para designar secretos que pertenecen solo a Dios pero que él revela graciosamente a sus siervos. Cuando Nabucodonosor exige tanto el sueño como su interpretación, Daniel apela al «Dios del cielo» que revela los misterios (Dan 2:28). La evidencia multilingüe es notablemente uniforme: el español «misterio», el inglés «mystery» y el alemán «Geheimnis» convergen en el mismo significado central. Este término sentó las bases para el vocabulario apocalíptico y rabínico posterior sobre la revelación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7332', 'spa', 'flaqueza, consunción; escasez, medida escasa', 'Este sustantivo describe condiciones de deficiencia—consunción corporal, flaqueza inducida por hambruna, o medidas escasas. Isaías lo usa para emaciación física (''flaqueza''), contrastando salud con consunción. El Salmo 106 recuerda que Dios envió ''flaqueza a su alma'' cuando concedió el deseo de Israel por carne—saciedad física produciendo consunción espiritual. Miqueas condena el ''efa escaso'', usando el término para medidas deshonestas y reducidas que engañan a los clientes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7336', 'spa', 'Gobernante, dignatario, potentado — participio Qal usado como sustantivo para personas de autoridad y poder politico', 'Sustantivo participial de una raiz que significa ''ser de peso'' o ''imponente'', usado exclusivamente en plural para designar gobernantes y potentados. La palabra conlleva un sentido de gravedad y autoridad establecida, y aparece con frecuencia en paralelo con ''reyes'' (melakhim) para formar un cuadro completo del poder terrenal. Debora convoca a estos gobernantes a escuchar su canto de victoria (Jue 5:3), mientras que el Sal 2:2 los retrata conspirando juntos contra el ungido del Senor. Proverbios personifica a la Sabiduria como aquella por quien los gobernantes decretan justicia (Prov 8:15), e Isaias declara con retórica elevada que Dios reduce a nada a los gobernantes del mundo (Isa 40:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7337', 'spa', 'Ser o hacer ancho, ensanchar; referido a territorio, fronteras, boca y corazón; Hifil: ampliar, dar espacio; Qal: hacerse ancho; Nifal: espacioso', 'Ser o hacer ancho, ensanchar; referido a territorio, fronteras, boca y corazón; Hifil: ampliar, dar espacio; Qal: hacerse ancho; Nifal: espacioso');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7339', 'spa', 'Plaza abierta, explanada, lugar amplio: el espacio público de una ciudad, generalmente cerca de la puerta', 'Plaza abierta, explanada, lugar amplio: el espacio público de una ciudad, generalmente cerca de la puerta');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7340', 'spa', 'Rejob — topónimo de localidades cerca de Hamat, en Aser, y también nombres personales de un rey arameo y un levita.', 'Rejob (que significa «lugar amplio» o «plaza abierta») designa varias localidades distintas en la tierra de Israel, sobre todo una ciudad cerca de la entrada de Hamat en el extremo norte y una ciudad levítica en el territorio de Aser. El nombre también pertenece al menos a dos individuos: un rey arameo mencionado en 2 Samuel y un levita postexílico que selló el pacto en Nehemías. El Rejob geográfico cerca de Hamat marcó el límite septentrional del reconocimiento de los espías en Números 13:21, mientras que el Rejob aserita aparece en las listas de repartición y entre las ciudades levíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7341', 'spa', 'Anchura, amplitud: medida lateral de una estructura, objeto o extensión; ocasionalmente figurado para vastedad de entendimiento.', 'רֹחַב es el término hebreo estándar para la medida de lado a lado, con 101 apariciones concentradas casi exclusivamente en especificaciones arquitectónicas y geográficas. Domina las descripciones constructivas del tabernáculo (Éx 25-27), el templo de Salomón (1 R 6-7) y el templo visionario de Ezequiel (Ez 40-42), donde se empareja regularmente con אֹרֶךְ (longitud) y a veces con קוֹמָה (altura) para dar dimensiones completas. Más allá de la medición, la palabra se abre ocasionalmente a la metáfora: ''anchura de corazón'' describe la vasta comprensión de Salomón, tan amplia como la arena a la orilla del mar (1 R 5:9), e Isaías emplea ''la anchura de tu tierra'' para evocar la soberanía de Emanuel sobre toda Judá (Is 8:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7342', 'spa', 'Ancho, amplio, espacioso; idiomáticamente: orgulloso (ancho de corazón), libre (en lugar amplio) o codicioso (ancho de apetito).', 'Ancho, amplio, espacioso; idiomáticamente: orgulloso (ancho de corazón), libre (en lugar amplio) o codicioso (ancho de apetito).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7343', 'spa', 'Rajab, la ramera de Jericó que dio refugio a los espías de Israel', 'Mujer cananea de Jericó que escondió a los dos espías israelitas y fue perdonada cuando cayó la ciudad. Su historia en Josué 2 y 6 avanza desde el ocultamiento (Jos 2:1, 3) hasta el juramento de protección (Jos 6:17) y el rescate (Jos 6:23, 25). Se convirtió en ejemplo célebre de fe en el Nuevo Testamento (Heb 11:31; Stg 2:25) y aparece en la genealogía de Jesús según Mateo (Mt 1:5). Su nombre, que significa ''ancha'' o ''amplia'', contrasta con las estrechas murallas de Jericó que ella ayudó a franquear.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7344', 'spa', 'Rejobot (topónimo, ''lugares amplios, espacio'')', 'Este topónimo, que significa «lugares amplios» o «espacio», identifica tres ubicaciones distintas: un distrito cercano a Nínive, un pozo que cavó Isaac como símbolo de liberación de la contienda, y una ciudad asociada con un rey edomita. El nombre refleja el valor antiguo de la libertad espacial y el alivio de encontrar un territorio sin disputas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7345', 'spa', 'Rehabías, nieto de Moisés por línea de Eliezer; nombre teofórico que significa ''Yah ha ensanchado''', 'Nombre levítico que significa ''Yah ha ensanchado'' o ''Yah ha dado amplitud,'' llevado por el hijo de Eliezer y nieto de Moisés. Sus cinco apariciones se concentran en las genealogías levíticas de Crónicas, donde su linaje se rastrea para las asignaciones del servicio del templo. En 1 Crónicas 23:17 se establece su descendencia, 24:21 registra la división sacerdotal de sus descendientes, y 26:25 vincula a su familia con los tesoros consagrados por David. El nombre evoca la raíz רָחַב (''ser amplio''), sugiriendo la generosidad divina al expandir la herencia de alguien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7346', 'spa', 'Roboam — hijo de Salomón y primer rey del reino dividido de Judá, cuya dureza provocó la escisión de la nación.', 'Roboam — hijo de Salomón y primer rey del reino dividido de Judá, cuya dureza provocó la escisión de la nación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7347', 'spa', 'Molino de mano, piedras de moler (forma dual que designa el par de piedras para moler grano)', 'La forma dual hebrea designa el par de piedras planas empleadas para moler grano, un utensilio doméstico omnipresente en el antiguo Israel. Éxodo 11:5 lo sitúa junto a la sierva que muele en el molino. Números 11:8 describe a los israelitas moliendo el maná con piedras de moler. Deuteronomio 24:6 prohíbe tomar las piedras de molino como prenda, pues equivaldría a arrebatar el sustento de una familia. Isaías 47:2 humilla a Babilonia ordenándole tomar las piedras de moler como esclava. Jeremías 25:10 incluye el sonido del molino entre los ruidos cotidianos que cesarán durante el juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7348a', 'spa', 'Rejum (nombre propio, ''compasión, misericordia'')', 'Este nombre postexílico, que probablemente significa «compasión» o «ternura» a partir de la raíz רחם, identifica a varios individuos que regresaron con Zorobabel y colaboraron con Nehemías. Las variantes textuales y los pasajes paralelos muestran cierta confusión en la transmisión del nombre, con posible identificación con otros personajes de nombre similar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7348b', 'spa', 'Rehum (nombre de un oficial persa)', 'Este nombre designa a un oficial persa que se opuso a la reconstrucción de los muros de Jerusalén en Esdras 4. A diferencia del nombre israelita Rehum (derivado de ''compasión''), este posiblemente proviene del iranio antiguo rukma, que significa ''esplendor'', reflejando una etimología persa y no hebrea. El papel de este funcionario como corresponsal real ilustra la supervisión administrativa persa sobre Judá en el período postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7349', 'spa', 'Compasivo, misericordioso; atributo divino emparejado con ''clemente,'' que define el caracter pactual de Dios. Casi exclusivamente un epiteto divino, e', 'Compasivo, misericordioso; atributo divino emparejado con ''clemente,'' que define el caracter pactual de Dios. Casi exclusivamente un epiteto divino, este adjetivo forma parte de la gran formula credal proclamada por primera vez en el Sinai: ''El SENOR, el SENOR, Dios compasivo y clemente'' (Ex 34:6). Ese binomio -- רַחוּם וְחַנּוּן -- resuena a lo largo de las Escrituras como un estribillo liturgico (Sal 86:15; 103:8; 111:4; 145:8; Joel 2:13; Jonas 4:2; Neh 9:17, 31; 2 Cr 30:9). La raiz רחם se conecta con el vientre materno, otorgando a esta compasion una cualidad visceral y maternal. Solo una vez (Sal 112:4) se aplica a un ser humano, modelando el caracter divino en la vida humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7350', 'spa', 'Lejano, distante, remoto — espacial, temporal o adverbialmente (''desde lejos''); también como sustantivo: distancia.', 'Lejano, distante, remoto — espacial, temporal o adverbialmente (''desde lejos''); también como sustantivo: distancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7353', 'spa', 'oveja hembra, oveja (animal de rebaño)', 'Este sustantivo designa a la oveja hembra, frecuentemente mencionada junto con carneros y cabras, o empleada en símiles. El término aparece en relatos patriarcales describiendo rebaños, en la imaginería profética del siervo sufriente y en comparaciones poéticas. Las ovejas representaban ganado valioso y portaban un peso simbólico significativo en el sacrificio y la metáfora bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7354', 'spa', 'Raquel: la esposa amada de Jacob, hija de Labán, madre de José y Benjamín', 'Raquel: la esposa amada de Jacob, hija de Labán, madre de José y Benjamín');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7355', 'spa', 'Tener compasión, mostrar misericordia; Piel: ejercer activamente un cuidado tierno; Pual: recibir misericordia; relacionado con rechem (''útero'')', 'Tener compasión, mostrar misericordia; Piel: ejercer activamente un cuidado tierno; Pual: recibir misericordia; relacionado con rechem (''útero'')');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7356a', 'spa', 'Matriz, útero; ''desde la matriz'' (es decir, desde el nacimiento)', 'El órgano físico de la gestación, portador de un profundo peso teológico en el pensamiento hebreo. Génesis 49:25 incluye las bendiciones de la matriz entre las bendiciones patriarcales. Jueces 5:30 emplea una vívida forma dual en el cántico de Débora. Proverbios 30:16 menciona la matriz estéril entre cuatro cosas que nunca se sacian. Isaías 46:3 usa ''desde la matriz'' para expresar el cuidado de Dios desde el primer instante de la existencia. Ezequiel 20:26 conecta al primogénito de la matriz con los sacrificios idolátricos de Israel. El término funciona tanto en sentido literal como en la expresión temporal ''desde el vientre,'' indicando origen o destino desde antes del nacimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7356b', 'spa', 'Compasión, tiernas misericordias: sentimiento visceral profundo de misericordia, frecuentemente como atributo divino (plurale intensivum)', 'Compasión, tiernas misericordias: sentimiento visceral profundo de misericordia, frecuentemente como atributo divino (plurale intensivum)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7358', 'spa', 'vientre, matriz — el útero como órgano de concepción y nacimiento, usado tanto literalmente como en expresiones figuradas de origen', 'vientre, matriz — el útero como órgano de concepción y nacimiento, usado tanto literalmente como en expresiones figuradas de origen');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7364', 'spa', 'Lavar, bañar o enjuagar con agua; abarca el baño completo para purificación, el lavado de objetos o partes del cuerpo, y la recepción pasiva del lavam', 'Lavar, bañar o enjuagar con agua; abarca el baño completo para purificación, el lavado de objetos o partes del cuerpo, y la recepción pasiva del lavamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7368', 'spa', 'Estar lejos, ser distante; alejar, apartar; irse lejos, retirarse; mantenerse lejos de, abstenerse; extender, ensanchar.', 'Estar lejos, ser distante; alejar, apartar; irse lejos, retirarse; mantenerse lejos de, abstenerse; extender, ensanchar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7376', 'spa', 'Estrellar, despedazar violentamente; usado para la matanza brutal de niños en contextos de guerra', 'Verbo de violencia estremecedora, empleado casi exclusivamente para describir la atrocidad bélica de estrellar niños contra las rocas o el suelo. En su forma activa Piel, designa el acto del perpetrador: Hazael ''estrellará'' a los niños de Israel (2 Re 8:12). En el Pual pasivo, describe a las víctimas: los niños de Samaria ''fueron estrellados'' (Os 13:16), y los de Nínive igualmente (Nah 3:10). Aunque aparece solo seis veces, carga un enorme peso profético, señalando la consecuencia más extrema de la infidelidad al pacto y la crueldad imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7378', 'spa', 'Contender, disputar, reñir; pleitear o litigar una causa; como sustantivo: disputa o pleito.', 'Contender, disputar, reñir; pleitear o litigar una causa; como sustantivo: disputa o pleito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7379', 'spa', 'Causa legal o pleito; contienda o riña entre partes; disputa o controversia pública.', 'Causa legal o pleito; contienda o riña entre partes; disputa o controversia pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7381', 'spa', 'Olor, aroma o fragancia; con mayor frecuencia el grato aroma sacrificial que asciende a Dios, pero también fragancias naturales y reputación figurada.', 'Olor, aroma o fragancia; con mayor frecuencia el grato aroma sacrificial que asciende a Dios, pero también fragancias naturales y reputación figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7385', 'spa', 'Vacuidad, vanidad; futilidad o falta de propósito; concretamente, estar físicamente vacío o hueco', 'Sustantivo que transmite el sentido de vacuidad, tanto abstracta como concreta. En la mayoría de sus apariciones figura en frases adverbiales que significan ''en vano'' o ''sin propósito'' — trabajo que no produce nada (Is 49:4; Lv 26:16, 20), adoración que resulta fútil (Sal 2:1), o esfuerzo gastado para nada (Jr 51:58; Hab 2:13). El alemán Nichtigkeit (''nulidad'') capta el peso filosófico, mientras que el español en vano transmite la futilidad práctica. Un único uso concreto en Jeremías 51:34 describe a Nabucodonosor dejando a Israel físicamente ''vacío'' — devorando y desechando a la nación como un recipiente vaciado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7386', 'spa', 'Vacio, vacante; tambien de personas: inutil, ocioso; de actividades: vano, futil. Un adjetivo vivido que se mueve de lo concreto a lo moral. En su sen', 'Vacio, vacante; tambien de personas: inutil, ocioso; de actividades: vano, futil. Un adjetivo vivido que se mueve de lo concreto a lo moral. En su sentido mas literal describe una cisterna seca (Gen 37:24), espigas marchitas de grano (Gen 41:27) o cantaros vacios llevados por los hombres de Gedeon (Jue 7:16). Cuando se aplica a personas, el tono cambia drasticamente: ''hombres indignos'' que siguen a Abimelec (Jue 9:4) o los ''vacios'' ante quienes David danzo (2 Sam 6:20). Proverbios lo extiende un paso mas hacia las actividades futiles en si mismas: las ''vanidades'' de quienes persiguen cosas vacias (Pr 12:11; 28:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7387', 'spa', 'De vacío, con las manos vacías, sin nada; figuradamente: en vano, sin causa ni propósito.', 'De vacío, con las manos vacías, sin nada; figuradamente: en vano, sin causa ni propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7389a', 'spa', 'Pobreza, carencia, indigencia — la condición de privación material y vulnerabilidad económica', 'Presente exclusivamente en Proverbios, este sustantivo designa la cruda realidad de la privación material. Aparece en sentencias sapienciales que contrastan la pobreza con la riqueza (Pr 30:8, opuesto a עֹשֶׁר) y con la seguridad del rico (Pr 10:15). La literatura sapiencial lo trata como consecuencia de la pereza (6:11; 24:34) o de perseguir fantasías (28:19), convirtiéndolo en una categoría tanto económica como moral dentro del pensamiento sapiencial hebreo. Su núcleo semántico es estable y unívoco: carencia de recursos materiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7390', 'spa', 'Tierno, delicado, suave: joven o frágil de cuerpo; apacible o manso en el habla; pusilánime, tímido de ánimo.', 'Tierno, delicado, suave: joven o frágil de cuerpo; apacible o manso en el habla; pusilánime, tímido de ánimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7392', 'spa', 'Verbo de movimiento y dominio que abarca burros, caballos, carros y las nubes del cielo. El participio Qal רֹכֵב funciona prácticamente como sustantiv', 'Verbo de movimiento y dominio que abarca burros, caballos, carros y las nubes del cielo. El participio Qal רֹכֵב funciona prácticamente como sustantivo — ''jinete'' o ''auriga'' — desde el «caballo y su jinete» del Cántico del Mar (Éx 15:1) hasta Dios como Aquel que «cabalga los cielos» (Dt 33:26). El Hifil causativo aparece en momentos de entronización y honor: a José lo hicieron montar en el segundo carro de Faraón (Gn 41:43), a Salomón lo sentaron sobre la mula de David (1 R 1:33). Una extensión poco frecuente del Hifil significa simplemente «cargar mercancía sobre un animal», como cuando el arca fue colocada sobre un carro nuevo (2 S 6:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7393', 'spa', 'Carro de guerra o fuerza de carros (colectivo militar); raramente, la piedra de molino superior.', 'El principal término militar para vehículos bélicos con ruedas en la Biblia hebrea, que abarca desde los carros de Faraón en el mar Rojo (Éx 14:7) hasta los carros de hierro de los cananeos (Jos 17:16) y las ciudades de carros de Salomón (1 R 9:19). Árabe مَرْكَبَة y coreano 병거 confirman la lectura de vehículo de guerra a través de familias lingüísticas. Un fascinante sentido secundario aparece solo tres veces: la piedra de molino superior, la que ''cabalga'' sobre la inferior; la mujer de Tebes dejó caer una sobre la cabeza de Abimelec (Jue 9:53). La metáfora de la raíz ר-כ-ב (''montar, cabalgar'') enlaza ambos sentidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7394', 'spa', 'Recab (רֵכָב); nombre propio que posiblemente significa ''jinete'' o ''auriga'', llevado por al menos tres personajes bíblicos. Recab hijo de Rimón el bee', 'Recab (רֵכָב); nombre propio que posiblemente significa ''jinete'' o ''auriga'', llevado por al menos tres personajes bíblicos. Recab hijo de Rimón el beerotita asesinó a Is-boset y fue ejecutado por David (2 Sam 4:2–12). De mayor relevancia, Recab fue el ancestro —a través de Jonadab hijo de Recab— de la comunidad recabita, cuya estricta abstinencia de vino y vida nómada Jeremías presentó como modelo de fidelidad (Jer 35:6–19). Un tercer Recab, padre de Malquías, reparó una puerta de Jerusalén bajo Nehemías (Neh 3:14). Primer Crónicas 2:55 vincula a los recabitas con orígenes ceneos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7395', 'spa', 'conductor de carro, auriga; jinete, soldado montado', 'Este sustantivo designa personal militar que monta o conduce—ya sea conductores de carros o caballería montada. El término aparece en narrativas de batalla y contextos reales, distinguiendo entre diferentes tipos de jinetes militares. Crónicas y Reyes lo usan para el auriga profesional que conduce el carro de guerra del rey, mientras que 2 Reyes también lo aplica a un jinete montado o explorador de caballería.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7397a', 'spa', 'los recabitas (gentilicio, descendientes de Recab)', 'Esta designación gentilicia identifica a la casa de los recabitas, un grupo conservador descendiente de Recab que mantenía un estricto estilo de vida nómada, absteniéndose del vino, la agricultura y la vivienda permanente. Jeremías 35 los presenta como modelo de fidelidad a los mandatos ancestrales, contrastando su obediencia con la ruptura del pacto por parte de Judá. Representan un compromiso contracultural dentro de la sociedad israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7399', 'spa', 'Propiedad, posesiones o bienes; riqueza mueble que incluye ganado, pertenencias y botín de conquista', 'Propiedad, posesiones o bienes; riqueza mueble que incluye ganado, pertenencias y botín de conquista');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7400', 'spa', 'Calumnia, chisme malicioso; también la persona que lo practica: calumniador, chismoso, delator', 'Palabra que abarca tanto la actividad del chisme malicioso como la persona que lo ejerce. Levítico 19:16 prohíbe ''andar como chismoso'' entre el pueblo, usando רָכִיל en su sentido de agente. Proverbios 11:13 y 20:19 advierten que el chismoso revela secretos. En Jeremías y Ezequiel, el enfoque se desplaza hacia la práctica abstracta: Jer 6:28 llama a los israelitas rebeldes ''andadores de calumnia,'' y Ez 22:9 denuncia a ''hombres de calumnia'' dentro de Jerusalén. El español distingue con claridad ambos sentidos: ''calumnia'' para el acto abstracto y ''calumniador/chismoso'' para el agente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7401', 'spa', 'Ser tierno, blando o débil (de corazón o palabras); en Hifil, ablandar o debilitar la resolución de alguien.', 'Verbo que proyecta una sola cualidad física —la blandura— sobre un rico paisaje de estados emocionales y morales. Las palabras pueden ser ''más suaves que el aceite'' y sin embargo ocultar espadas (Sal 55:21); una herida puede quedar sin curar, no ''suavizada'' con ungüento (Isa 1:6, Pual). Pero con mayor frecuencia la blandura es del corazón: el temor que hace desfallecer el valor antes de la batalla (Dt 20:3), o la ternura penitente ante la palabra de Dios, como cuando el corazón de Josías ''se enterneció'' y se humilló (2 Re 22:19; 2 Cr 34:27). El español distingue bellamente: ''blandas'' para palabras suaves, ''desfallezca'' para el valor que flaquea, mientras que la única raíz hebrea mantiene ambos sentidos unidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7402', 'spa', 'Comerciante, mercader; tratante profesional de mercancías, usado con frecuencia del comercio internacional de Tiro.', 'Comerciante, mercader; tratante profesional de mercancías, usado con frecuencia del comercio internacional de Tiro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7404', 'spa', 'comercio, tráfico, mercancía', 'Este sustantivo denota la actividad comercial —el tráfico mercantil— y las mercancías involucradas en el intercambio. Aparece exclusivamente en los oráculos de Ezequiel contra Tiro, donde captura las extensas redes comerciales de la ciudad marítima. El término deriva de la raíz que designa al mercader ambulante, subrayando el movimiento inherente al comercio antiguo y la identidad de Tiro como imperio mercantil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7408', 'spa', 'Adquirir, reunir bienes — acumular posesiones, especialmente ganado y riqueza mueble', 'Este verbo aparece exclusivamente en las narrativas patriarcales de Génesis, siempre en la fuente sacerdotal, describiendo la acumulación de bienes muebles: ganado, siervos y posesiones. Abraham adquiere bienes en Harán (Gn 12:5), Jacob acumula rebaños y propiedades en Padán-Aram (31:18), y la familia lleva consigo todo lo adquirido al migrar a Egipto (46:6). El verbo aparece siempre emparejado con רְכֻשׁ (posesiones/bienes) como acusativo cognado, subrayando la naturaleza deliberada y acumulativa de la adquisición. No se trata de recibir pasivamente, sino de reunir activamente riqueza transportable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7409', 'spa', 'corceles, caballos veloces (monturas reales de caballería)', 'Este sustantivo colectivo designa caballos de alta calidad o corceles, particularmente monturas veloces de caballería o caballos reales. Distinguidos de los caballos comunes, son animales de prestigio: los caballos de los carros de Salomón, las monturas de los correos reales persas y los caballos que tiran de carros en la imaginería profética. El término enfatiza la velocidad y la nobleza del animal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7410', 'spa', 'Ram — nombre propio de un ancestro de David y de la familia de Elihú', 'Ram es un nombre propio hebreo que aparece en dos contextos genealógicos distintos. En primer lugar y de manera destacada, Ram es hijo de Hezrón y padre de Aminadab en la línea que va de Judá a David (Rut 4:19; 1 Cr 2:9-10), lo que lo convierte en antepasado del Mesías. En segundo lugar, un hijo de Jerameel llevó el mismo nombre (1 Cr 2:25, 27). El nombre también identifica al clan de Elihú en Job 32:2, aunque algunos eruditos lo consideran una designación separada. Todas las lenguas modernas lo conservan sin traducir, confirmando su carácter de nombre propio irreductible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7411a', 'spa', 'lanzar, arrojar, disparar (flechas o proyectiles)', 'Este verbo denota la accion de lanzar, arrojar o disparar, especialmente con arco y flecha. Es celebre por el Cantico del Mar, donde Dios ''arrojo'' al ejercito del faraon al mar, y tambien describe a arqueros y flecheros. La raiz tiene amplia conexion en las lenguas semiticas para el acto de lanzar o disparar, enfatizando la proyeccion con fuerza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7411b', 'spa', 'Piel: engañar, embaucar o actuar con traición; también una forma Qal con sentido de «alzada, elevada».', 'El Piel de esta raíz denota engaño interpersonal y traición: la amarga sorpresa de descubrir que uno ha sido embaucado. El engaño de Labán a Jacob en la noche de bodas (Gn 29:25) establece el patrón: «¿Por qué me has engañado?». El mismo verbo aparece cuando Mical, esposa de Saúl, ayuda a David a escapar (1 Sam 19:17), cuando la adivina de Endor descubre que ha sido engañada (1 Sam 28:12) y cuando se expone la artimaña de los gabaonitas (Jos 9:22). Una sola forma participial Qal en Núm 15:30, que significa «con mano alzada» (es decir, con desafío), pertenece probablemente a la raíz homónima que significa «estar alto».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7412', 'spa', 'Arrojar o lanzar (arameo); de personas echadas como castigo; también colocar/poner, o figuradamente imponer tributo', 'Verbo arameo que domina las narraciones dramáticas de Daniel, donde describe el acto aterrador de arrojar personas al horno de fuego ardiente o al foso de los leones. Las formas Pe''al, Pe''il y Hithpe''el juntas abarcan diez de sus doce apariciones, todas involucrando el lanzamiento físico de personas como castigo (Dn 3:6, 11, 15, 20, 21, 24; 6:8, 13, 17, 25). El español ''arrojamos/echaron'' y el francés ''jeter'' (lanzar) expresan consistentemente este acto violento. Aparecen dos sentidos extendidos: la solemne ''colocación'' de tronos en Daniel 7:9, y la figurada ''imposición'' de tributo en Esdras 7:24.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7413', 'spa', 'plataforma elevada, lugar alto — santuario levantado para culto ilícito', 'Término técnico del ámbito cultual que designa una plataforma elevada o montículo erigido para el culto, casi sinónimo de בָּמָה pero con connotaciones marcadamente negativas. Cuatro de sus cinco apariciones se concentran en Ezequiel 16:24-39, donde el profeta condena a Jerusalén por construir estos santuarios en cada encrucijada para la prostitución idolátrica. La única aparición restante, en 1 Samuel 22:6, podría referirse a una altura o lugar elevado en un sentido más general, posiblemente conectada con el topónimo Ramá. El español ''lugar alto'' conserva bien el matiz espacial de elevación presente en el original hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7414', 'spa', 'Ramá: ''la Altura,'' ciudad en Benjamín asociada con el ministerio de Samuel y el llanto de Raquel', 'Ramá: ''la Altura,'' ciudad en Benjamín asociada con el ministerio de Samuel y el llanto de Raquel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7415', 'spa', 'rimmah — gusano o larva, signo y agente de descomposición y mortalidad humana', 'Sustantivo femenino que designa gusanos o larvas: los organismos que se alimentan de carne en descomposición y que, por ello, simbolizan la corrupción y la mortalidad. La palabra aparece casi exclusivamente en contextos de muerte, juicio e insignificancia humana. En Éxodo 16:24 su ausencia es notable: el maná conservado por mandato de Dios no produjo gusanos. Job recurre a rimmah repetidamente como meditación sobre la mortalidad: «Mi carne está vestida de gusanos» (Job 7:5), «Al gusano digo: tú eres mi madre» (Job 17:14). Isaías la empareja con tole''ah como lecho ignominioso del rey caído de Babilonia (Is 14:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7416', 'spa', 'Granada; el fruto usado en ofrendas y decoración del templo, o el árbol mismo como cultivo agrícola', 'Granada; el fruto usado en ofrendas y decoración del templo, o el árbol mismo como cultivo agrícola');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7417a', 'spa', 'Rimón, deidad aramea de la tormenta adorada en Damasco', 'Rimón era una deidad aramea, probablemente un dios de tormenta y clima relacionado con el asirio Rammanu (también asociado con truenos y lluvia). El nombre aparece exclusivamente en referencia a ''la casa de Rimón'', el templo en Damasco donde el rey sirio adoraba y donde su comandante Naamán se sentía obligado a acompañarlo. Segunda de Reyes 5:18 registra la petición angustiada de Naamán pidiendo perdón cuando debe inclinarse en el templo de Rimón mientras sostiene al rey—una escena que revela las tensiones religiosas que enfrentan los conversos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7417b', 'spa', 'Rimón, nombre personal de un benjamita de Beerot', 'Este Rimón (distinto de la deidad y nombres de lugares) era un hombre de Beerot en Benjamín, padre de Recab y Baana. Sus hijos fueron capitanes militares bajo Is-boset que asesinaron al hijo de Saúl, trayendo su cabeza a David con esperanza de recompensa. David en cambio los ejecutó por matar a un hombre justo en su casa, luego exhibió sus cuerpos públicamente. El nombre Rimón evidentemente se usaba tanto para deidades como para personas en el antiguo Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7417c', 'spa', 'Rimón — topónimo de ciudades en Simeón, Zabulón y Benjamín, frecuentemente asociado con terreno rocoso o elevado.', 'Rimón (que significa «granada») identifica varias ciudades en los territorios tribales de Israel. Al sur aparece como ciudad en la heredad de Simeón (Jos 15:32; 19:7), a veces emparejada con En-rimón. En el norte, un Rimón en Zabulón servía como ciudad levítica (Jos 19:13; 1 Cr 6:62). Quizá lo más dramático es que la Peña de Rimón en Benjamín sirvió de refugio a seiscientos guerreros benjaminitas sobrevivientes tras la devastadora guerra civil narrada en Jueces 20-21. Zacarías 14:10 también menciona el Rimón meridional como punto geográfico de referencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7420', 'spa', 'Lanza — arma de acometida con asta larga, armamento militar estándar en el antiguo Israel. El רֹמַח (romaj) es una lanza de acometida, distinta de la ', 'Lanza — arma de acometida con asta larga, armamento militar estándar en el antiguo Israel. El רֹמַח (romaj) es una lanza de acometida, distinta de la jabalina más ligera (חֲנִית). Aparece junto a la espada, el escudo y el arco como parte del equipamiento habitual del guerrero. Finees famosamente empuñó una para ejecutar juicio en Baal-peor (Nm 25:7), y los profetas de Baal se cortaban con lanzas en el Monte Carmelo (1 Re 18:28). La inversión escatológica de Joel —''forjad de vuestras podaderas lanzas'' (Jl 4:10)— invierte la visión de paz de Isaías. Los cognados abarcan el arameo (rumchaa), el árabe (rumh) y el etiópico (remh), lo que sugiere un vocabulario militar semítico compartido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7423a', 'spa', 'Engaño, traición; falsedad en el habla o el carácter, frecuentemente emparejado con mentira e injusticia.', 'El sustantivo רְמִיָּה denota engaño o traición, casi siempre en contextos de habla deshonesta o carácter desleal. Se empareja naturalmente con שֶׁקֶר («falsedad») y עַוְלָה («injusticia»), formando un campo léxico en torno a la falta de fiabilidad moral. Miqueas 6:12 condena a una ciudad cuya lengua es רְמִיָּה, y el Salmo 120:2-3 suplica ser librado de una «lengua engañosa». La impactante imagen de un קֶשֶׁת רְמִיָּה, un «arco traicionero» (Os 7:16; Sal 78:57), describe algo que parece confiable pero que falla catastróficamente al tensarlo, vívida metáfora de la infidelidad de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7423b', 'spa', 'negligencia, desidia, flojedad — descuido culpable en el trabajo o el deber', 'Derivado de la raíz que significa ''ser flojo,'' este sustantivo aparece en Proverbios y una vez en Jeremías para describir el defecto moral de la pereza y la negligencia. En Proverbios caracteriza la ''mano negligente'' que produce pobreza (10:4), la persona indolente destinada al trabajo forzado (12:24) y el apetito adormecido (19:15). Jeremías 48:10 lo eleva a su contexto más severo: realizar la obra de Jehová ''con negligencia'' acarrea maldición. El abanico semántico del español oscila entre ''negligencia,'' ''pereza'' y hasta ''engaño,'' reflejando cómo la desidia puede deslizarse hacia la omisión culpable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7425', 'spa', 'Remalías (רְמַלְיָהוּ); nombre propio que identifica al padre de Pécaj, quien usurpó el trono de Israel mediante asesinato (2 Re 15:25). El nombre apa', 'Remalías (רְמַלְיָהוּ); nombre propio que identifica al padre de Pécaj, quien usurpó el trono de Israel mediante asesinato (2 Re 15:25). El nombre aparece casi exclusivamente en la fórmula patronímica ''Pécaj hijo de Remalías'' en Reyes, Isaías y Crónicas. El uso deliberado de Isaías de ''el hijo de Remalías'' sin el título real (Is 7:4–5, 9; 8:6) constituye una negativa intencionada a dignificar al usurpador, reduciéndolo al nombre de su padre. Las formas en español (Remalías), francés (Remalia) y alemán (Remaljahu) reflejan la terminación teofórica -yahu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7426', 'spa', 'Levantarse, ser exaltado; forma paralela de rum (H7311), también usada para retirarse del peligro', 'Forma paralela del verbo común rum (ser alto, exaltado), que aparece en contextos de elevación física y exaltación divina. En la visión del carro-trono de Ezequiel, los querubines ''se elevaron'' repetidamente (Ez 10:15, 17, 19), capturando el movimiento ascendente. Isaías 33:10 lo emplea para la autoexaltación de Dios: ''Ahora me levantaré.'' Un uso distintivo ocurre en Números 16:45, donde se ordena a Moisés y Aarón ''apartarse'' de la congregación antes de que caiga el juicio; aquí el movimiento ascendente se transforma en retirada física urgente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7429', 'spa', 'Pisotear o hollar con fuerza, aplastar bajo los pies; figuradamente, oprimir o abrumar; en voz pasiva: ser pisoteado.', 'Pisotear o hollar con fuerza, aplastar bajo los pies; figuradamente, oprimir o abrumar; en voz pasiva: ser pisoteado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7430', 'spa', 'Arrastrarse, pulular, moverse por el suelo; dicho de criaturas pequeñas que se deslizan o reptan sobre la tierra.', 'Arrastrarse, pulular, moverse por el suelo; dicho de criaturas pequeñas que se deslizan o reptan sobre la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7431', 'spa', 'Reptil, animal rastrero; sustantivo colectivo para las criaturas pequeñas que se mueven por el suelo en los textos de creación y legislación.', 'Reptil, animal rastrero; sustantivo colectivo para las criaturas pequeñas que se mueven por el suelo en los textos de creación y legislación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7433', 'spa', 'Ramot, nombre propio que designa ciudades en Israel, especialmente la ciudad fortificada de Ramot de Galaad.', 'Ramot, nombre propio que designa ciudades en Israel, especialmente la ciudad fortificada de Ramot de Galaad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7440', 'spa', 'Grito vibrante de gozo o clamor de suplica; canto jubiloso de alabanza o clamor urgente de lamento.', 'Grito vibrante de gozo o clamor de suplica; canto jubiloso de alabanza o clamor urgente de lamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7442b', 'spa', 'Verbo onomatopéyico cuyo sonido mismo evoca la cualidad vibrante y resonante de un grito: רָנַן capta el estallido vocal incontenible de adoración y c', 'Verbo onomatopéyico cuyo sonido mismo evoca la cualidad vibrante y resonante de un grito: רָנַן capta el estallido vocal incontenible de adoración y celebración. Cuando el pueblo vio caer fuego sobre el primer sacrificio de Aarón, «gritaron de gozo y cayeron sobre sus rostros» (Lv 9:24). Las estrellas del alba «cantaron juntas» en la creación (Job 38:7). A Sion, la estéril, se le ordena «¡Canta!» porque sus hijos superarán a los de la casada (Is 54:1). El Piel intensifica esto en jubilación sostenida y exuberante — los justos «cantan con gozo» en sus lechos (Sal 149:5) — y el Hifil causativo describe a Dios mismo haciendo que las salidas de la mañana y la tarde «griten de alegría» (Sal 65:8). El cognado árabe ranna (''clamar en voz alta, vibrar'') conserva el núcleo acústico: un sonido que resuena y reverbera.');